function(container, apiUrl, tables) {
  // DOM要素の取得
  const loginForm = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password-link');

  // ログイン試行回数を追跡
  let loginAttempts = parseInt(localStorage.getItem('loginAttempts') || '0');
  let lockoutTime = parseInt(localStorage.getItem('lockoutTime') || '0');

  // アカウントロック状態をチェック
  function isAccountLocked() {
    if (lockoutTime && Date.now() < lockoutTime) {
      return true;
    }
    if (lockoutTime && Date.now() >= lockoutTime) {
      // ロック期間が過ぎた場合はリセット
      localStorage.removeItem('loginAttempts');
      localStorage.removeItem('lockoutTime');
      loginAttempts = 0;
    }
    return false;
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  // エラーメッセージ非表示
  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // バリデーション
  function validateForm() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック（XSS/SQLインジェクション対策）
    const dangerousChars = /<script|javascript:|DROP\s+TABLE|SELECT\s+\*|INSERT\s+INTO|DELETE\s+FROM/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // アカウントロックチェック
      if (isAccountLocked()) {
        showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        return false;
      }

      // ユーザーテーブル（tables[0]）からユーザー情報を取得
      const users = await window.aivicApi.list(0);
      if (!users) {
        showError('システムエラーが発生しました');
        return false;
      }

      // ユーザー認証（実際の実装では暗号化されたパスワードと比較）
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        // ログイン失敗回数を増加
        loginAttempts++;
        localStorage.setItem('loginAttempts', loginAttempts.toString());

        if (loginAttempts >= 5) {
          // 5回失敗でアカウントロック（30分）
          const lockTime = Date.now() + (30 * 60 * 1000);
          localStorage.setItem('lockoutTime', lockTime.toString());
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return false;
      }

      // 簡易パスワード検証（実際の実装ではハッシュ比較）
      // ここでは demo 用に固定パスワード "password123" を使用
      if (password !== 'password123') {
        loginAttempts++;
        localStorage.setItem('loginAttempts', loginAttempts.toString());

        if (loginAttempts >= 5) {
          const lockTime = Date.now() + (30 * 60 * 1000);
          localStorage.setItem('lockoutTime', lockTime.toString());
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return false;
      }

      // ログイン成功 - 試行回数をリセット
      localStorage.removeItem('loginAttempts');
      localStorage.removeItem('lockoutTime');

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // セッション情報を保存
      const sessionData = {
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        displayName: user.氏名,
        department: user.所属部署,
        role: user.権限レベル,
        loginTime: new Date().toISOString()
      };

      if (rememberMe) {
        localStorage.setItem('userSession', JSON.stringify(sessionData));
      } else {
        sessionStorage.setItem('userSession', JSON.stringify(sessionData));
      }

      return true;
    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました');
      return false;
    }
  }

  // パスワード表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁';
  });

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateForm()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();
    const rememberMe = rememberMeCheckbox.checked;

    const loginSuccess = await handleLogin(userId, password, rememberMe);

    if (loginSuccess) {
      // 工数記録画面に遷移
      window.showScreen("scr-1778907133295");
    }
  });

  // パスワード忘れリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面への遷移（実装時に適切な画面IDに変更）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // 既存のログイン状態をチェック
  const existingSession = localStorage.getItem('userSession') || sessionStorage.getItem('userSession');
  if (existingSession) {
    try {
      const sessionData = JSON.parse(existingSession);
      // セッションが有効な場合は自動的にメイン画面に遷移
      window.showScreen("scr-1778907133295");
    } catch (error) {
      // セッションデータが無効な場合はクリア
      localStorage.removeItem('userSession');
      sessionStorage.removeItem('userSession');
    }
  }

  // ホバー効果
  const loginButton = container.querySelector('#login-button');
  loginButton.addEventListener('mouseenter', () => {
    loginButton.style.background = 'var(--primary-hover)';
  });
  loginButton.addEventListener('mouseleave', () => {
    loginButton.style.background = 'var(--primary)';
  });

  // フォーカス時のスタイル
  [userIdInput, passwordInput].forEach(input => {
    input.addEventListener('focus', () => {
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
      input.style.outline = 'none';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let workTimer = null;
  let startTime = null;
  let pausedTime = 0;
  let pauseStartTime = null;
  let isWorking = false;
  let isPaused = false;

  // 現在日時更新
  function updateCurrentDateTime() {
    const now = new Date();
    const dateStr = now.toLocaleDateString('ja-JP') + ' ' + now.toLocaleTimeString('ja-JP');
    container.querySelector('#current-datetime').textContent = dateStr;
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!isWorking || !startTime) return;

    const now = new Date();
    let elapsed = now - startTime - pausedTime;

    if (isPaused && pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    container.querySelector('#elapsed-time').textContent = timeStr;
  }

  // 作業項目選択肢を読み込み
  function loadWorkItems() {
    const select = container.querySelector('#work-item-select');
    const workItems = tables[3]?.records || []; // 作業項目マスタ

    select.innerHTML = '<option value="">作業項目を選択してください</option>';
    workItems.filter(item => item.有効フラグ).forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
      select.appendChild(option);
    });
  }

  // 本日の作業履歴を表示
  function renderTodayHistory() {
    const tbody = container.querySelector('#today-history-tbody');
    const today = new Date().toISOString().split('T')[0];

    window.aivicApi.list(1).then(records => {
      if (!records) return;

      const todayRecords = records.filter(r => {
        const workDate = new Date(r.作業日).toISOString().split('T')[0];
        return workDate === today;
      }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

      tbody.innerHTML = todayRecords.map(record => {
        const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
        const endTime = record.作業終了時刻? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '--:--';
        const workHours = record.作業時間 ? (record.作業時間 / 60).toFixed(1) : '0.0';

        return `
          <tr data-id="${record.作業記録ID}">
            <td>${startTime}</td>
            <td>${endTime}</td>
            <td>${record.作業種別 || ''}</td>
            <td>${workHours}h</td>
            <td>0</td>
            <td>${record.作業内容 || ''}</td>
            <td><span style="font-size: 11px; padding: 2px 6px; border-radius: 3px; background: ${record.進捗状況 === '完了' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(59, 130, 246, 0.2)'}; color: ${record.進捗状況 === '完了' ? '#4ade80' : '#60a5fa'};">${record.進捗状況}</span></td>
          </tr>
        `;
      }).join('');

      // 集計情報更新
      const totalMinutes = todayRecords.reduce((sum, r) => sum + (r.作業時間 || 0), 0);
      const totalHours = (totalMinutes / 60).toFixed(1);
      container.querySelector('#total-hours').textContent = `${totalHours}時間`;
      container.querySelector('#total-count').textContent = `${todayRecords.length}件`;
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 作業開始
  function startWork() {
    const workItemId = container.querySelector('#work-item-select').value;
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    startTime = new Date();
    pausedTime = 0;
    isWorking = true;
    isPaused = false;

    // UI更新
    container.querySelector('#start-work-btn').disabled = true;
    container.querySelector('#pause-work-btn').disabled = false;
    container.querySelector('#end-work-btn').disabled = false;
    container.querySelector('#work-status').textContent = '作業中';
    container.querySelector('#start-time-display').textContent = startTime.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});

    // タイマー開始
    workTimer = setInterval(updateElapsedTime, 1000);

    // 作業記録作成
    const workItems = tables[3]?.records || [];
    const selectedItem = workItems.find(item => item.作業項目ID === workItemId);

    currentWorkRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証情報から取得
      作業日: startTime.toISOString(),
      作業開始時刻: startTime.toISOString(),
      プロジェクト名: 'デフォルトプロジェクト',
      作業場所: '現場A',
      作業種別: selectedItem?.作業項目名 || '',
      作業内容: '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };
  }

  // 作業中断
  function pauseWork() {
    if (!isWorking) {
      showError('作業が開始されていません');
      return;
    }

    container.querySelector('#pause-reason-modal').classList.remove('hidden');
  }

  // 中断確定
  function confirmPause() {
    const category = container.querySelector('#pause-reason-category').value;
    const detail = container.querySelector('#pause-reason-detail').value.trim();

    if (!category) {
      showError('中断理由を選択してください');
      return;
    }

    pauseStartTime = new Date();
    isPaused = true;

    // UI更新
    container.querySelector('#work-status').textContent = '中断中';
    container.querySelector('#pause-work-btn').textContent = '再開';
    container.querySelector('#pause-reason-modal').classList.add('hidden');

    // 中断記録保存
    const pauseRecord = {
      作業記録ID: currentWorkRecord?.作業記録ID || 'temp-id',
      中断開始日時: pauseStartTime.toISOString(),
      中断理由区分: category,
      中断理由詳細: detail,
      対応状況: '対応中',
      記録者ID: 'current-user-id'
    };

    window.aivicApi.save(2, pauseRecord);

    // フォームクリア
    container.querySelector('#pause-reason-category').value = '';
    container.querySelector('#pause-reason-detail').value = '';
  }

  // 作業再開
  function resumeWork() {
    if (!isPaused) return;

    const pauseDuration = new Date() - pauseStartTime;
    pausedTime += pauseDuration;
    isPaused = false;
    pauseStartTime = null;

    // UI更新
    container.querySelector('#work-status').textContent = '作業中';
    container.querySelector('#pause-work-btn').textContent = '中断';

    const pauseMinutes = Math.floor(pausedTime / (1000 * 60));
    container.querySelector('#pause-time-display').textContent = `${Math.floor(pauseMinutes / 60)}:${(pauseMinutes % 60).toString().padStart(2, '0')}`;
  }

  // 作業終了
  function endWork() {
    if (!isWorking) {
      showError('作業が開始されていません');
      return;
    }

    const endTime = new Date();
    const totalMinutes = Math.floor((endTime - startTime - pausedTime) / (1000 * 60));

    // タイマー停止
    if (workTimer) {
      clearInterval(workTimer);
      workTimer = null;
    }

    // 作業記録更新
    if (currentWorkRecord) {
      currentWorkRecord.作業終了時刻 = endTime.toISOString();
      currentWorkRecord.作業時間 = totalMinutes;
      currentWorkRecord.進捗状況 = '完了';
      currentWorkRecord.作業内容 = container.querySelector('#work-memo').value;
    }

    // UI リセット
    isWorking = false;
    isPaused = false;
    startTime = null;
    pausedTime = 0;
    pauseStartTime = null;

    container.querySelector('#start-work-btn').disabled = false;
    container.querySelector('#pause-work-btn').disabled = true;
    container.querySelector('#pause-work-btn').textContent = '中断';
    container.querySelector('#end-work-btn').disabled = true;
    container.querySelector('#work-status').textContent = '完了';
    container.querySelector('#elapsed-time').textContent = '00:00:00';
    container.querySelector('#start-time-display').textContent = '--:--';
    container.querySelector('#pause-time-display').textContent = '00:00';

    // 履歴更新
    renderTodayHistory();
  }

  // 保存
  function saveWork() {
    if (!currentWorkRecord) {
      showError('保存する作業記録がありません');
      return;
    }

    window.aivicApi.save(1, currentWorkRecord).then(result => {
      if (result) {
        container.querySelector('#save-status').textContent = '保存済み';
        container.querySelector('#work-memo').value = '';
        renderTodayHistory();
      }
    });
  }

  // キャンセル
  function cancelWork() {
    if (isWorking && !confirm('作業中です。キャンセルしますか？')) {
      return;
    }

    // タイマー停止
    if (workTimer) {
      clearInterval(workTimer);
      workTimer = null;
    }

    // 状態リセット
    isWorking = false;
    isPaused = false;
    startTime = null;
    pausedTime = 0;
    pauseStartTime = null;
    currentWorkRecord = null;

    // UI リセット
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-memo').value = '';
    container.querySelector('#start-work-btn').disabled = false;
    container.querySelector('#pause-work-btn').disabled = true;
    container.querySelector('#pause-work-btn').textContent = '中断';
    container.querySelector('#end-work-btn').disabled = true;
    container.querySelector('#work-status').textContent = '待機中';
    container.querySelector('#elapsed-time').textContent = '00:00:00';
    container.querySelector('#start-time-display').textContent = '--:--';
    container.querySelector('#pause-time-display').textContent = '00:00';
    container.querySelector('#save-status').textContent = '未保存';
  }

  // 文字数カウンター
  function setupCharCounter(textareaId, counterId) {
    const textarea = container.querySelector(textareaId);
    const counter = container.querySelector(counterId);

    textarea.addEventListener('input', () => {
      counter.textContent = textarea.value.length;
    });
  }

  // イベントリスナー設定
  container.querySelector('#start-work-btn').addEventListener('click', startWork);

  container.querySelector('#pause-work-btn').addEventListener('click', () => {
    if (isPaused) {
      resumeWork();
    } else {
      pauseWork();
    }
  });

  container.querySelector('#end-work-btn').addEventListener('click', endWork);
  container.querySelector('#save-work-btn').addEventListener('click', saveWork);
  container.querySelector('#cancel-work-btn').addEventListener('click', cancelWork);

  // 中断モーダル
  container.querySelector('#cancel-pause-btn').addEventListener('click', () => {
    container.querySelector('#pause-reason-modal').classList.add('hidden');
  });

  container.querySelector('#confirm-pause-btn').addEventListener('click', confirmPause);

  // 文字数カウンター設定
  setupCharCounter('#work-memo', '#memo-count');
  setupCharCounter('#pause-reason-detail', '#pause-reason-count');

  // 初期化
  loadWorkItems();
  renderTodayHistory();
  updateCurrentDateTime();

  // 1秒ごとに現在時刻更新
  setInterval(updateCurrentDateTime, 1000);
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  const errorMessage = container.querySelector("#error-message");
  const noResults = container.querySelector("#no-results");

  let allRecords = [];
  let interruptCounts = {};

  // 中断回数を計算する関数
  function calculateInterruptCounts(workRecords, interruptRecords) {
    const counts = {};
    workRecords.forEach(work => {
      const interrupts = interruptRecords.filter(interrupt => interrupt.作業記録ID === work.作業記録ID);
      counts[work.作業記録ID] = interrupts.length;
    });
    return counts;
  }

  // 作業時間を分から時間:分形式に変換
  function formatWorkTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 時刻フォーマット
  function formatTime(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = "block";
    setTimeout(() => {
      errorMessage.style.display = "none";
    }, 5000);
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (rows.length === 0) {
      tbody.innerHTML = "";
      noResults.style.display = "block";
      return;
    }

    noResults.style.display = "none";
    tbody.innerHTML = rows.map(r => {
      const interruptCount = interruptCounts[r.作業記録ID] || 0;
      return `
        <tr data-id="${r.作業記録ID}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDateTime(r.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.作業種別 || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(r.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: center;">${interruptCount}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${r.進捗状況 === '完了' ? 'rgba(34, 197, 94, 0.2)' : r.進捗状況 === '作業中' ? 'rgba(59, 130, 246, 0.2)' : 'rgba(239, 68, 68, 0.2)'}; color: var(--text);">${r.進捗状況 || ""}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${r.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録
      const interruptRecords = await window.aivicApi.list(2); // 中断記録

      if (workRecords && interruptRecords) {
        allRecords = workRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
        interruptCounts = calculateInterruptCounts(workRecords, interruptRecords);
        renderRows(allRecords);
      } else {
        // API未接続時は初期データを使用
        allRecords = (tables[1]?.records || []).sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
        interruptCounts = calculateInterruptCounts(tables[1]?.records || [], tables[2]?.records || []);
        renderRows(allRecords);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      allRecords = (tables[1]?.records || []).sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
      interruptCounts = calculateInterruptCounts(tables[1]?.records || [], tables[2]?.records || []);
      renderRows(allRecords);
    }
  }

  // 日付バリデーション
  function validateDateRange(startDate, endDate) {
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    if (startDate && startDate > today) {
      return "開始日に未来の日付は選択できません";
    }

    if (endDate && endDate > today) {
      return "終了日に未来の日付は選択できません";
    }

    if (startDate && endDate && startDate > endDate) {
      return "開始日は終了日より前の日付を入力してください";
    }

    if (startDate && endDate) {
      const diffTime = Math.abs(endDate - startDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        return "1年以上の期間は選択できません";
      }
    }

    return null;
  }

  // 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const startDateStr = container.querySelector("#start-date").value;
    const endDateStr = container.querySelector("#end-date").value;
    const statusFilter = container.querySelector("#status-filter").value;

    // 日付範囲未選択チェック
    if (!startDateStr && !endDateStr) {
      showError("日付範囲を選択してください");
      return;
    }

    const startDate = startDateStr ? new Date(startDateStr) : null;
    const endDate = endDateStr ? new Date(endDateStr + "T23:59:59") : null;

    // 日付バリデーション
    const validationError = validateDateRange(startDate, endDate);
    if (validationError) {
      showError(validationError);
      return;
    }

    try {
      const workRecords = await window.aivicApi.list(1);
      const interruptRecords = await window.aivicApi.list(2);

      if (workRecords && interruptRecords) {
        interruptCounts = calculateInterruptCounts(workRecords, interruptRecords);

        let filteredRecords = workRecords.filter(record => {
          const recordDate = new Date(record.作業日);

          // 日付フィルター
          if (startDate && recordDate < startDate) return false;
          if (endDate && recordDate > endDate) return false;

          // ステータスフィルター
          if (statusFilter && record.進捗状況 !== statusFilter) return false;

          return true;
        });

        filteredRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
        renderRows(filteredRecords);
      }
    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  });

  // リセットボタンのイベントリスナー
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelector("#status-filter").value = "";
    renderRows(allRecords);
  });

  // CSVエクスポートボタンのイベントリスナー
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const workRecords = await window.aivicApi.list(1);
      const interruptRecords = await window.aivicApi.list(2);

      if (workRecords && interruptRecords) {
        const counts = calculateInterruptCounts(workRecords, interruptRecords);

        const headers = ["作業日時", "作業項目", "開始時刻", "終了時刻", "作業時間", "中断回数", "状況"];
        const csvContent = [
          "\uFEFF" + headers.join(","),
          ...workRecords.map(record => {
            const interruptCount = counts[record.作業記録ID] || 0;
            return [
              `"${formatDateTime(record.作業日)}"`,
              `"${record.作業種別 || ""}"`,
              `"${formatTime(record.作業開始時刻)}"`,
              `"${formatTime(record.作業終了時刻)}"`,
              `"${formatWorkTime(record.作業時間)}"`,
              `"${interruptCount}"`,
              `"${record.進捗状況 || ""}"`
            ].join(",");
          })
        ].join("\n");

        const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = "work_history_export.csv";
        link.click();
      }
    } catch (error) {
      console.error("CSVエクスポートエラー:", error);
      showError("CSVエクスポート中にエラーが発生しました");
    }
  });

  // データ抽出ボタンのイベントリスナー
  container.querySelector("#btn-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  // 戻るボタンのイベントリスナー
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentUser = { id: 'user-001', name: '田中太郎' };
  let activeWorks = [];
  let pausedWorks = [];
  let workItems = [];

  // 現在日時を更新する関数
  function updateCurrentDateTime() {
    const now = new Date();
    const dateStr = now.getFullYear() + '/' + 
                   String(now.getMonth() + 1).padStart(2, '0') + '/' + 
                   String(now.getDate()).padStart(2, '0') + ' ' +
                   String(now.getHours()).padStart(2, '0') + ':' + 
                   String(now.getMinutes()).padStart(2, '0');
    container.querySelector('#current-datetime').textContent = dateStr;
  }

  // 経過時間を計算する関数
  function calculateElapsedTime(startTime) {
    const now = new Date();
    const start = new Date(startTime);
    const diffMs = now - start;
    const hours = Math.floor(diffMs / (1000 * 60 * 60));
    const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}時間${minutes}分`;
  }

  // 進行中作業一覧を描画する関数
  function renderActiveWorks() {
    const container_elem = container.querySelector('#active-works-container');
    const noActiveWorks = container.querySelector('#no-active-works');
    const activeWorksList = container.querySelector('#active-works-list');
    const tbody = container.querySelector('#active-works-tbody');

    if (activeWorks.length === 0) {
      noActiveWorks.style.display = 'block';
      activeWorksList.style.display = 'none';
    } else {
      noActiveWorks.style.display = 'none';
      activeWorksList.style.display = 'block';

      tbody.innerHTML = activeWorks.map(work => {
        const workItem = workItems.find(item => item.id === work.workItemId);
        const workItemName = workItem ? workItem.name : '不明な作業項目';
        const startTime = new Date(work.startTime).toLocaleString('ja-JP');
        const elapsedTime = calculateElapsedTime(work.startTime);

        return `
          <tr data-id="${work.id}">
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workItemName}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${elapsedTime}</td>
            <td style="padding: 6px 10px;">
              <button class="action-btn" data-testid="work-detail-button" onclick="window.showScreen('scr-1778907296658')" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">
                工数入力
              </button>
            </td>
          </tr>
        `;
      }).join('');
    }
  }

  // 中断中作業一覧を描画する関数
  function renderPausedWorks() {
    const container_elem = container.querySelector('#paused-works-container');
    const noPausedWorks = container.querySelector('#no-paused-works');
    const pausedWorksList = container.querySelector('#paused-works-list');
    const tbody = container.querySelector('#paused-works-tbody');

    if (pausedWorks.length === 0) {
      noPausedWorks.style.display = 'block';
      pausedWorksList.style.display = 'none';
    } else {
      noPausedWorks.style.display = 'none';
      pausedWorksList.style.display = 'block';

      tbody.innerHTML = pausedWorks.map(work => {
        const workItem = workItems.find(item => item.id === work.workItemId);
        const workItemName = workItem ? workItem.name : '不明な作業項目';
        const pauseTime = new Date(work.pauseTime).toLocaleString('ja-JP');

        return `
          <tr data-id="${work.id}">
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workItemName}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${pauseTime}</td>
            <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.pauseReason || '未入力'}</td>
            <td style="padding: 6px 10px;">
              <button class="resume-work-btn action-btn" data-id="${work.id}" data-testid="resume-work-button" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">
                再開
              </button>
            </td>
          </tr>
        `;
      }).join('');
    }
  }

  // 作業項目選択肢を描画する関数
  function renderWorkItems() {
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">選択してください</option>' + 
      workItems.map(item => `<option value="${item.id}">${item.name}</option>`).join('');
  }

  // 確認ダイアログを表示する関数
  function showConfirmDialog(title, message, onConfirm) {
    const dialog = container.querySelector('#confirm-dialog');
    const titleElem = container.querySelector('#confirm-title');
    const messageElem = container.querySelector('#confirm-message');
    const okBtn = container.querySelector('#confirm-ok');
    const cancelBtn = container.querySelector('#confirm-cancel');

    titleElem.textContent = title;
    messageElem.textContent = message;
    dialog.style.display = 'flex';

    const handleOk = () => {
      dialog.style.display = 'none';
      okBtn.removeEventListener('click', handleOk);
      cancelBtn.removeEventListener('click', handleCancel);
      onConfirm();
    };

    const handleCancel = () => {
      dialog.style.display = 'none';
      okBtn.removeEventListener('click', handleOk);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    okBtn.addEventListener('click', handleOk);
    cancelBtn.addEventListener('click', handleCancel);
  }

  // エラーメッセージを表示する関数
  function showError(message) {
    const errorElem = container.querySelector('#error-message');
    errorElem.textContent = message;
    errorElem.style.display = 'block';
    setTimeout(() => {
      errorElem.style.display = 'none';
    }, 5000);
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 作業項目マスタを読み込み (tableIndex: 3)
      const workItemsData = await window.aivicApi.list(3);
      if (workItemsData) {
        workItems = workItemsData.filter(item => item.有効フラグ === true)
                                .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
                                .map(item => ({
          id: item.作業項目ID,
          name: item.作業項目名,
          code: item.作業項目コード,
          category: item.カテゴリ,
          standardHours: item.標準工数時間
        }));
      }

      // 作業記録から進行中・中断中の作業を読み込み (tableIndex: 1)
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        activeWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && record.進捗状況 === '作業中'
        ).map(record => ({
          id: record.作業記録ID,
          workItemId: record.作業項目ID,
          startTime: record.作業開始時刻,
          location: record.作業場所,
          content: record.作業内容
        }));

        // 中断記録から中断中作業を取得 (tableIndex: 2)
        const pauseRecords = await window.aivicApi.list(2);
        if (pauseRecords) {
          pausedWorks = pauseRecords.filter(record => 
            record.対応状況 === '対応中' && !record.中断終了日時
          ).map(record => {
            const workRecord = workRecords.find(wr => wr.作業記録ID === record.作業記録ID);
            return {
              id: record.中断記録ID,
              workRecordId: record.作業記録ID,
              workItemId: workRecord ? workRecord.作業項目ID : null,
              pauseTime: record.中断開始日時,
              pauseReason: record.中断理由詳細
            };
          });
        }
      }

      renderWorkItems();
      renderActiveWorks();
      renderPausedWorks();
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
    }
  }

  // 備考文字数カウンター
  const notesInput = container.querySelector('#work-notes-input');
  const notesCounter = container.querySelector('#notes-counter');
  notesInput.addEventListener('input', () => {
    notesCounter.textContent = notesInput.value.length;
  });

  // 記録開始ボタンのイベントリスナー
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const location = container.querySelector('#work-location-input').value.trim();
    const notes = container.querySelector('#work-notes-input').value.trim();

    // バリデーション
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    // 既に進行中の作業があるかチェック
    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return;
    }

    // 作業場所の文字数チェック
    if (location.length > 100) {
      showError('作業場所は100文字以内で入力してください');
      return;
    }

    // 備考の文字数チェック
    if (notes.length > 500) {
      showError('備考は500文字以内で入力してください');
      return;
    }

    // XSS対策: 不正文字チェック
    if (location.includes('<script>') || location.includes('</script>')) {
      showError('作業場所に不正な文字が含まれています');
      return;
    }

    try {
      const now = new Date().toISOString();
      const workRecord = {
        作業員ID: currentUser.id,
        作業日: now,
        作業開始時刻: now,
        作業終了時刻: null,
        作業時間: null,
        プロジェクト名: 'デフォルトプロジェクト',
        作業場所: location || '',
        作業種別: '一般作業',
        作業内容: notes || '',
        進捗状況: '作業中',
        備考: notes || '',
        承認状態: '未承認',
        作成者ID: currentUser.id,
        作業項目ID: workItemId
      };

      const savedRecord = await window.aivicApi.save(1, workRecord);
      if (savedRecord) {
        // フォームをクリア
        container.querySelector('#work-item-select').value = '';
        container.querySelector('#work-location-input').value = '';
        container.querySelector('#work-notes-input').value = '';
        notesCounter.textContent = '0';

        // データを再読み込み
        await loadInitialData();

        // 工数入力画面に遷移
        window.showScreen('scr-1778907296658');
      } else {
        showError('工数記録の開始に失敗しました');
      }
    } catch (error) {
      console.error('工数記録開始エラー:', error);
      showError('工数記録の開始に失敗しました');
    }
  });

  // 中断作業再開のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-work-btn');
    if (resumeBtn) {
      const pauseRecordId = resumeBtn.dataset.id;
      const pausedWork = pausedWorks.find(work => work.id === pauseRecordId);

      if (!pausedWork) {
        showError('指定された作業が見つかりません');
        return;
      }

      showConfirmDialog(
        '作業再開確認',
        '中断中の作業を再開しますか？',
        async () => {
          try {
            // 中断記録を終了
            const now = new Date().toISOString();
            await window.aivicApi.update(2, pauseRecordId, {
              中断終了日時: now,
              対応状況: '解決済み'
            });

            // 作業記録を作業中に戻す
            await window.aivicApi.update(1, pausedWork.workRecordId, {
              進捗状況: '作業中'
            });

            // データを再読み込み
            await loadInitialData();
          } catch (error) {
            console.error('作業再開エラー:', error);
            showError('作業の再開に失敗しました');
          }
        }
      );
    }
  });

  // ログアウトボタンのイベントリスナー
  container.querySelector('#btn-logout').addEventListener('click', () => {
    showConfirmDialog(
      'ログアウト確認',
      'ログアウトしますか？',
      () => {
        window.location.href = './login.html';
      }
    );
  });

  // 設定ボタンのイベントリスナー
  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面への遷移（画面IDは仮）
    alert('設定画面は未実装です');
  });

  // 現在日時の定期更新
  updateCurrentDateTime();
  setInterval(updateCurrentDateTime, 60000); // 1分ごとに更新

  // 経過時間の定期更新
  setInterval(() => {
    if (activeWorks.length > 0) {
      renderActiveWorks();
    }
  }, 60000); // 1分ごとに更新

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 現在の作業記録データ（実際の実装では前画面から渡される）
  let currentWorkRecord = {
    id: 'work-001',
    startTime: '09:00',
    endTime: '17:30',
    totalTime: '8:30',
    breakTime: '1:00',
    actualWorkTime: '7:30',
    workItemName: 'システム保守作業',
    workLocation: 'データセンター A棟',
    workerName: '田中 太郎'
  };

  // DOM要素の取得
  const workMemoInput = container.querySelector('#work-memo');
  const completionStatusSelect = container.querySelector('#completion-status');
  const hasIssueCheckbox = container.querySelector('#has-issue');
  const issueContentWrapper = container.querySelector('#issue-content-wrapper');
  const issueContentInput = container.querySelector('#issue-content');
  const errorMessage = container.querySelector('#error-message');
  const memoCount = container.querySelector('#memo-count');
  const issueCount = container.querySelector('#issue-count');

  // 文字数カウンター
  workMemoInput.addEventListener('input', () => {
    memoCount.textContent = workMemoInput.value.length;
  });

  issueContentInput.addEventListener('input', () => {
    issueCount.textContent = issueContentInput.value.length;
  });

  // 異常報告チェックボックスの制御
  hasIssueCheckbox.addEventListener('change', () => {
    if (hasIssueCheckbox.checked) {
      issueContentWrapper.classList.remove('hidden');
      issueContentInput.required = true;
    } else {
      issueContentWrapper.classList.add('hidden');
      issueContentInput.required = false;
      issueContentInput.value = '';
      issueCount.textContent = '0';
    }
  });

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // バリデーション関数
  function validateForm() {
    hideError();

    // 完了状況必須チェック
    if (!completionStatusSelect.value) {
      showError('完了状況を選択してください。');
      return false;
    }

    // 作業メモ文字数チェック
    if (workMemoInput.value.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    // 異常報告チェック時の異常内容必須チェック
    if (hasIssueCheckbox.checked) {
      if (!issueContentInput.value.trim()) {
        showError('異常報告をチェックした場合は、異常内容を入力してください。');
        return false;
      }
      if (issueContentInput.value.length > 500) {
        showError('異常内容は500文字以内で入力してください。');
        return false;
      }
    }

    return true;
  }

  // 記録確定ボタンのイベントリスナー
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    if (!validateForm()) {
      return;
    }

    try {
      // 作業記録の更新
      const workRecordData = {
        作業終了時刻: new Date().toISOString(),
        作業時間: parseInt(currentWorkRecord.actualWorkTime.split(':')[0]) * 60 + parseInt(currentWorkRecord.actualWorkTime.split(':')[1]),
        作業内容: workMemoInput.value || '',
        進捗状況: completionStatusSelect.value,
        備考: workMemoInput.value || '',
        承認状態: '未承認'
      };

      const updatedRecord = await window.aivicApi.update(1, currentWorkRecord.id, workRecordData);

      if (updatedRecord) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssueCheckbox.checked && issueContentInput.value.trim()) {
          const anomalyData = {
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentWorkRecord.id,
            ユーザーID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
            異常値種別: '作業異常報告',
            検出項目: '作業内容',
            検出値: issueContentInput.value,
            閾値: '正常範囲',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: true,
            検出日時: new Date().toISOString()
          };

          await window.aivicApi.save(4, anomalyData);
        }

        alert('工数記録が正常に確定されました。');
        // 前画面に戻る（実際の実装では適切な画面に遷移）
        window.history.back();
      } else {
        showError('記録の保存に失敗しました。もう一度お試しください。');
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
