  confirmBtn.addEventListener('mouseenter', () => {
    confirmBtn.style.background = 'var(--primary-hover)';
  });
  confirmBtn.addEventListener('mouseleave', () => {
    confirmBtn.style.background = 'var(--primary)';
  });

  // 実作業時間の計算と表示更新
  function calculateActualWorkTime() {
    const startTime = container.querySelector('#start-time').textContent;
    const endTime = container.querySelector('#end-time').textContent;
    const breakTime = container.querySelector('#break-time').textContent;

    // 実際の実装では、開始時刻、終了時刻、中断時間から実作業時間を計算
    // ここではサンプル表示のまま
