function(container, apiUrl, tables) {
  let saveInterval = 30; // 保存間隔（秒）
  let autoSaveTimer = null;
  let isOnline = navigator.onLine;
  let pendingSyncCount = 0;
  let localData = JSON.parse(localStorage.getItem('workRecordsLocal') || '[]');

  // ローカルデータテーブル再描画
  function renderLocalData() {
    const tbody = container.querySelector('#local-data-tbody');
    if (localData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">ローカル保存データはありません</td></tr>';
      return;
    }

    tbody.innerHTML = localData.map(record => `
      <tr data-id="${record.id}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${new Date(record.作業日).toLocaleString()}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.プロジェクト名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.作業種別 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; ${record.synced ? 'background: rgba(34, 197, 94, 0.1); color: #22c55e;' : 'background: rgba(251, 191, 36, 0.1); color: #fbbf24;'}">
            ${record.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="delete-local-btn action-btn secondary" data-id="${record.id}" 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 2px 8px; border-radius: 3px; font-size: 11px; cursor: pointer;">
            削除
          </button>
        </td>
      </tr>
    `).join('');
  }

  // ステータス更新
  function updateStatus() {
    container.querySelector('#auto-save-status').textContent = autoSaveTimer ? '有効' : '無効';
    container.querySelector('#network-status').textContent = isOnline ? 'オンライン' : 'オフライン';
    container.querySelector('#pending-sync-count').textContent = `${pendingSyncCount}件`;

    const lastSave = localStorage.getItem('lastSaveTime');
    container.querySelector('#last-save-time').textContent = lastSave ? new Date(lastSave).toLocaleTimeString() : '--:--';
  }

  // エラー通知表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-notification');
    container.querySelector('#error-message').textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 自動保存開始
  function startAutoSave() {
    if (autoSaveTimer) clearInterval(autoSaveTimer);
    autoSaveTimer = setInterval(async () => {
      try {
        // 未同期データがあれば同期を試行
        const unsyncedData = localData.filter(record => !record.synced);
        if (unsyncedData.length > 0 && isOnline) {
          await syncLocalData();
        }
        localStorage.setItem('lastSaveTime', new Date().toISOString());
        updateStatus();
      } catch (error) {
        showError('自動保存中にエラーが発生しました: ' + error.message);
      }
    }, saveInterval * 1000);
    updateStatus();
  }

  // ローカルデータ同期
  async function syncLocalData() {
    const unsyncedData = localData.filter(record => !record.synced);
    let syncedCount = 0;

    for (const record of unsyncedData) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: record.作業員ID,
          作業日: record.作業日,
          作業開始時刻: record.作業開始時刻,
          作業終了時刻: record.作業終了時刻,
          作業時間: record.作業時間,
          プロジェクト名: record.プロジェクト名,
          作業場所: record.作業場所,
          作業種別: record.作業種別,
          作業内容: record.作業内容,
          進捗状況: record.進捗状況,
          備考: record.備考,
          承認状態: '未承認',
          作成者ID: record.作業員ID
        });

        if (saved) {
          record.synced = true;
          syncedCount++;
        }
      } catch (error) {
        console.error('同期エラー:', error);
      }
    }

    if (syncedCount > 0) {
      localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
      pendingSyncCount = localData.filter(r => !r.synced).length;
      renderLocalData();
      updateStatus();
    }

    return syncedCount;
  }

  // 初期化
  renderLocalData();
  updateStatus();

  // 未保存データチェック
  const hasUnsavedData = localStorage.getItem('hasUnsavedData') === 'true';
  if (hasUnsavedData) {
    container.querySelector('#recovery-notification').style.display = 'block';
  }

  // ネットワーク状態監視
  window.addEventListener('online', () => {
    isOnline = true;
    updateStatus();
    syncLocalData();
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    updateStatus();
  });

  // 保存間隔更新
  container.querySelector('#btn-update-interval').addEventListener('click', () => {
    const newInterval = parseInt(container.querySelector('#save-interval').value);
    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください');
      return;
    }
    if (newInterval > 86400) {
      showError('保存間隔は86400秒以下で設定してください');
      return;
    }

    saveInterval = newInterval;
    localStorage.setItem('autoSaveInterval', saveInterval.toString());
    startAutoSave();
  });

  // 手動同期実行
  container.querySelector('#btn-manual-sync').addEventListener('click', async () => {
    if (!isOnline) {
      showError('ネットワークに接続されていません');
      return;
    }

    try {
      const syncedCount = await syncLocalData();
      if (syncedCount > 0) {
        alert(`${syncedCount}件のデータを同期しました`);
      } else {
        alert('同期対象のデータがありません');
      }
    } catch (error) {
      showError('手動同期中にエラーが発生しました: ' + error.message);
    }
  });

  // データ復旧
  container.querySelector('#btn-recover-data').addEventListener('click', () => {
    localStorage.removeItem('hasUnsavedData');
    container.querySelector('#recovery-notification').style.display = 'none';
    window.showScreen('scr-1778907133295'); // 工数記録画面へ
  });

  container.querySelector('#btn-discard-data').addEventListener('click', () => {
    localStorage.removeItem('hasUnsavedData');
    localStorage.removeItem('unsavedWorkData');
    container.querySelector('#recovery-notification').style.display = 'none';
  });

  // ローカルデータクリア
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (!confirm('ローカル保存データをすべて削除しますか？\n※未同期のデータも削除されます。')) return;

    localStorage.removeItem('workRecordsLocal');
    localData = [];
    pendingSyncCount = 0;
    renderLocalData();
    updateStatus();
  });

  // 工数記録画面へ
  container.querySelector('#btn-work-records').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 行レベル操作（削除）
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      if (!confirm('このローカルデータを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      localData = localData.filter(record => record.id !== id);
      localStorage.setItem('workRecordsLocal', JSON.stringify(localData));
      pendingSyncCount = localData.filter(r => !r.synced).length;
      renderLocalData();
      updateStatus();
    }
  });

  // 保存間隔設定の復元
  const savedInterval = localStorage.getItem('autoSaveInterval');
  if (savedInterval) {
    saveInterval = parseInt(savedInterval);
    container.querySelector('#save-interval').value = saveInterval;
  }

  // 未同期件数の初期化
  pendingSyncCount = localData.filter(r => !r.synced).length;

  // 自動保存開始
  startAutoSave();
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let isRecording = false;

  // DOM要素の取得
  const form = container.querySelector('#interruption-form');
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const reasonSelect = container.querySelector('#reason');
  const locationInput = container.querySelector('#location');
  const detailsTextarea = container.querySelector('#details');
  const charCount = container.querySelector('#char-count');
  const durationDisplay = container.querySelector('#duration-display');
  const photoUpload = container.querySelector('#photo-upload');
  const photoBtn = container.querySelector('#photo-btn');
  const photoPreview = container.querySelector('#photo-preview');
  const previewImg = container.querySelector('#preview-img');
  const removePhotoBtn = container.querySelector('#remove-photo');
  const recordBtn = container.querySelector('#record-btn');
  const audioPreview = container.querySelector('#audio-preview');
  const previewAudio = container.querySelector('#preview-audio');
  const removeAudioBtn = container.querySelector('#remove-audio');
  const selectAllImpact = container.querySelector('#select-all-impact');
  const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
  const tempSaveBtn = container.querySelector('#temp-save-btn');
  const completeBtn = container.querySelector('#complete-btn');
  const errorMessage = container.querySelector('#error-message');

  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 文字数カウント
  detailsTextarea.addEventListener('input', () => {
    charCount.textContent = detailsTextarea.value.length;
  });

  // 中断時間の自動計算
  function updateDuration() {
    const start = startTimeInput.value;
    const end = endTimeInput.value;

    if (start && end) {
      const startDate = new Date(start);
      const endDate = new Date(end);
      const diffMs = endDate - startDate;

      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        durationDisplay.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
      } else {
        durationDisplay.textContent = '--:--';
      }
    } else {
      durationDisplay.textContent = '--:--';
    }
  }

  startTimeInput.addEventListener('change', updateDuration);
  endTimeInput.addEventListener('change', updateDuration);

  // 写真アップロード
  photoBtn.addEventListener('click', () => {
    photoUpload.click();
  });

  photoUpload.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      // ファイルサイズチェック（10MB）
      if (file.size > 10 * 1024 * 1024) {
        showError('ファイルサイズが上限（10MB）を超えています。');
        return;
      }

      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('対応していないファイル形式です。画像ファイルを選択してください。');
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        previewImg.src = e.target.result;
        photoPreview.style.display = 'block';
      };
      reader.readAsDataURL(file);
    }
  });

  removePhotoBtn.addEventListener('click', () => {
    photoUpload.value = '';
    photoPreview.style.display = 'none';
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    if (!isRecording) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (event) => {
          audioChunks.push(event.data);
        };

        mediaRecorder.onstop = () => {
          const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
          const audioUrl = URL.createObjectURL(audioBlob);
          previewAudio.src = audioUrl;
          audioPreview.style.display = 'block';

          stream.getTracks().forEach(track => track.stop());
        };

        mediaRecorder.start();
        isRecording = true;
        recordBtn.textContent = '⏹️ 録音停止';
        recordBtn.style.background = 'rgba(255,0,0,0.2)';
      } catch (error) {
        showError('録音に失敗しました。マイクへのアクセスを許可してください。');
      }
    } else {
      mediaRecorder.stop();
      isRecording = false;
      recordBtn.textContent = '🎤 録音開始';
      recordBtn.style.background = 'transparent';
    }
  });

  removeAudioBtn.addEventListener('click', () => {
    audioPreview.style.display = 'none';
    if (previewAudio.src) {
      URL.revokeObjectURL(previewAudio.src);
      previewAudio.src = '';
    }
  });

  // 影響範囲の全選択・全解除
  selectAllImpact.addEventListener('change', () => {
    impactCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllImpact.checked;
    });
  });

  // 個別選択での全選択チェックボックス連動
  impactCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      const allChecked = Array.from(impactCheckboxes).every(cb => cb.checked);
      const noneChecked = Array.from(impactCheckboxes).every(cb => !cb.checked);

      if (allChecked) {
        selectAllImpact.checked = true;
        selectAllImpact.indeterminate = false;
      } else if (noneChecked) {
        selectAllImpact.checked = false;
        selectAllImpact.indeterminate = false;
      } else {
        selectAllImpact.checked = false;
        selectAllImpact.indeterminate = true;
      }
    });
  });

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const start = startTimeInput.value;
    const reason = reasonSelect.value;
    const details = detailsTextarea.value;

    if (!start) {
      showError('中断開始時刻は必須です。');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です。');
      return false;
    }

    // 未来時刻チェック
    const startDate = new Date(start);
    const now = new Date();
    if (startDate > now) {
      showError('未来の時刻は入力できません。');
      return false;
    }

    // 文字数チェック
    if (details.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactValues = Array.from(container.querySelectorAll('input[name="impact"]:checked')).map(cb => cb.value);

    return {
      中断開始日時: startTimeInput.value,
      中断終了日時: endTimeInput.value || null,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value || null,
      中断時間: calculateDurationMinutes(),
      影響度: urgencyRadio ? urgencyRadio.value : '中',
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では認証情報から取得
      作業記録ID: 'current-work-record-id' // 実際の実装では現在の作業記録IDを取得
    };
  }

  function calculateDurationMinutes() {
    const start = startTimeInput.value;
    const end = endTimeInput.value;

    if (start && end) {
      const startDate = new Date(start);
      const endDate = new Date(end);
      const diffMs = endDate - startDate;
      return Math.max(0, Math.floor(diffMs / (1000 * 60)));
    }
    return null;
  }

  // 一時保存
  tempSaveBtn.addEventListener('click', async () => {
    const formData = collectFormData();

    try {
      // ローカルストレージに保存
      localStorage.setItem('temp_interruption_record', JSON.stringify(formData));

      // 成功メッセージ表示
      const successDiv = document.createElement('div');
      successDiv.textContent = '一時保存しました';
      successDiv.style.cssText = 'position: fixed; top: 20px; right: 20px; background: rgba(0,255,0,0.2); border: 1px solid rgba(0,255,0,0.5); color: #4ade80; padding: 8px 12px; border-radius: 6px; font-size: 13px; z-index: 1000;';
      document.body.appendChild(successDiv);

      setTimeout(() => {
        document.body.removeChild(successDiv);
      }, 3000);
    } catch (error) {
      showError('一時保存に失敗しました。');
    }
  });

  // 記録完了
  completeBtn.addEventListener('click', async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    const formData = collectFormData();

    try {
      // 中断記録テーブルのインデックスを取得（データ構造から推測）
      const interruptionTableIndex = tables.findIndex(table => 
        table.tableName && table.tableName.includes('中断') || 
        table.purpose && table.purpose.includes('中断')
      );

      const saved = await window.aivicApi.save(interruptionTableIndex >= 0 ? interruptionTableIndex : 2, formData);

      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('temp_interruption_record');

        // 作業再開記録画面に遷移
        window.showScreen("scr-1778907251446");
      } else {
        showError('記録の保存に失敗しました。ネットワーク接続を確認してください。');
      }
    } catch (error) {
      showError('記録の保存中にエラーが発生しました。');
    }
  });

  // 一時保存データの復元
  function restoreTempData() {
    try {
      const tempData = localStorage.getItem('temp_interruption_record');
      if (tempData) {
        const data = JSON.parse(tempData);

        if (data.中断開始日時) startTimeInput.value = data.中断開始日時;
        if (data.中断終了日時) endTimeInput.value = data.中断終了日時;
        if (data.中断理由区分) reasonSelect.value = data.中断理由区分;
        if (data.中断理由詳細) detailsTextarea.value = data.中断理由詳細;
        if (data.影響度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }

        // 文字数更新
        charCount.textContent = detailsTextarea.value.length;
        updateDuration();
      }
    } catch (error) {
      console.error('一時保存データの復元に失敗しました:', error);
    }
  }

  // 初期化時に一時保存データを復元
  restoreTempData();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedInterruptRecord = null;

  // DOM要素の取得
  const suspendedWorkTbody = container.querySelector('#suspended-work-tbody');
  const noSuspendedWork = container.querySelector('#no-suspended-work');
  const resumeForm = container.querySelector('#resume-form');
  const resumeTimeInput = container.querySelector('#resume-time');
  const resumeReasonSelect = container.querySelector('#resume-reason-select');
  const resumeReasonDetail = container.querySelector('#resume-reason-detail');
  const charCount = container.querySelector('#char-count');
  const errorMessage = container.querySelector('#error-message');
  const confirmDialog = container.querySelector('#resume-confirm-dialog');

  // 現在時刻を再開時刻に設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    resumeTimeInput.value = localDateTime;
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // 中断中作業一覧の描画
  function renderSuspendedWorks(workRecords, interruptRecords) {
    // 中断中の作業（進捗状況が「中断」）を抽出
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === '中断');

    if (suspendedWorks.length === 0) {
      suspendedWorkTbody.innerHTML = '';
      noSuspendedWork.classList.remove('hidden');
      return;
    }

    noSuspendedWork.classList.add('hidden');

    suspendedWorkTbody.innerHTML = suspendedWorks.map(work => {
      // 対応する中断記録を検索
      const interrupt = interruptRecords.find(int => int.作業記録ID === work.作業記録ID && !int.中断終了日時);
      const suspendTime = interrupt ? new Date(interrupt.中断開始日時).toLocaleString() : '-';
      const suspendReason = interrupt ? interrupt.中断理由詳細 || interrupt.中断理由区分 : '-';

      return `
        <tr data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${work.作業内容}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${suspendTime}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${suspendReason}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn select-work-btn" data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" style="padding: 4px 8px; font-size: 11px;">選択</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 選択された作業の詳細表示
  function showWorkDetails(workRecord, interruptRecord) {
    selectedWorkRecord = workRecord;
    selectedInterruptRecord = interruptRecord;

    container.querySelector('#selected-work-name').textContent = workRecord.作業内容;
    container.querySelector('#selected-suspend-time').textContent = 
      interruptRecord ? new Date(interruptRecord.中断開始日時).toLocaleString() : '-';
    container.querySelector('#selected-suspend-reason').textContent = 
      interruptRecord ? (interruptRecord.中断理由詳細 || interruptRecord.中断理由区分) : '-';

    setCurrentTime();
    resumeForm.classList.remove('hidden');
    hideError();
  }

  // 作業再開処理
  async function resumeWork() {
    if (!selectedWorkRecord || !selectedInterruptRecord) {
      showError('作業が選択されていません');
      return;
    }

    const resumeTime = resumeTimeInput.value;
    const reasonCategory = resumeReasonSelect.value;
    const reasonDetail = resumeReasonDetail.value.trim();

    // バリデーション
    if (!resumeTime) {
      showError('再開時刻を入力してください');
      return;
    }

    if (!reasonCategory && !reasonDetail) {
      showError('再開理由を入力または選択してください');
      return;
    }

    if (reasonDetail.length > 500) {
      showError('再開理由は500文字以内で入力してください');
      return;
    }

    try {
      // 中断記録を終了
      const updatedInterrupt = await window.aivicApi.update(2, selectedInterruptRecord.中断記録ID, {
        中断終了日時: new Date(resumeTime).toISOString(),
        更新日時: new Date().toISOString()
      });

      if (!updatedInterrupt) {
        showError('中断記録の更新に失敗しました');
        return;
      }

      // 作業記録の進捗状況を「作業中」に更新
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        更新日時: new Date().toISOString()
      });

      if (!updatedWork) {
        showError('作業記録の更新に失敗しました');
        return;
      }

      // 成功メッセージ表示後、工数入力画面に遷移
      alert('作業を再開しました');
      window.showScreen("scr-1778907296658");

    } catch (error) {
      showError('作業再開の処理中にエラーが発生しました');
      console.error('Resume work error:', error);
    }
  }

  // 文字数カウント更新
  resumeReasonDetail.addEventListener('input', () => {
    charCount.textContent = resumeReasonDetail.value.length;
  });

  // 初期データ読み込みと描画
  async function loadData() {
    try {
      const [workRecords, interruptRecords] = await Promise.all([
        window.aivicApi.list(1), // 作業記録
        window.aivicApi.list(2)  // 中断記録
      ]);

      renderSuspendedWorks(workRecords || [], interruptRecords || []);
    } catch (error) {
      console.error('Data loading error:', error);
      renderSuspendedWorks(tables[1]?.records || [], tables[2]?.records || []);
    }
  }

  // イベントリスナー設定
  container.addEventListener('click', async (e) => {
    // 作業選択ボタン
    const selectBtn = e.target.closest('.select-work-btn');
    if (selectBtn) {
      const workId = selectBtn.dataset.workId;
      const interruptId = selectBtn.dataset.interruptId;

      try {
        const [workRecords, interruptRecords] = await Promise.all([
          window.aivicApi.list(1),
          window.aivicApi.list(2)
        ]);

        const workRecord = workRecords.find(w => w.作業記録ID === workId);
        const interruptRecord = interruptRecords.find(i => i.中断記録ID === interruptId);

        if (workRecord) {
          showWorkDetails(workRecord, interruptRecord);
        }
      } catch (error) {
        showError('作業情報の取得に失敗しました');
      }
      return;
    }

    // 作業再開ボタン
    if (e.target.id === 'btn-resume') {
      confirmDialog.classList.remove('hidden');
      return;
    }

    // キャンセルボタン
    if (e.target.id === 'btn-cancel') {
      resumeForm.classList.add('hidden');
      selectedWorkRecord = null;
      selectedInterruptRecord = null;
      hideError();
      return;
    }

    // 戻るボタン
    if (e.target.id === 'btn-back') {
      history.back();
      return;
    }

    // ダイアログOKボタン
    if (e.target.id === 'dialog-ok') {
      confirmDialog.classList.add('hidden');
      await resumeWork();
      return;
    }

    // ダイアログキャンセルボタン
    if (e.target.id === 'dialog-cancel') {
      confirmDialog.classList.add('hidden');
      return;
    }
  });

  // ダイアログ背景クリックで閉じる
  confirmDialog.addEventListener('click', (e) => {
    if (e.target === confirmDialog) {
      confirmDialog.classList.add('hidden');
    }
  });

  // 初期化
  setCurrentTime();
  loadData();
}

function(container, apiUrl, tables) {
  // エラー情報の初期化
  let errorInfo = {
    title: 'システムエラーが発生しました',
    message: '申し訳ございません。予期しないエラーが発生しました。\nしばらく時間をおいてから再度お試しください。',
    code: 'E001',
    timestamp: new Date().toLocaleString('ja-JP'),
    type: 'general',
    details: {
      url: '/api/work-records',
      method: 'POST',
      status: 500,
      message: 'Internal Server Error',
      stack: 'TypeError: Cannot read property \'id\' of undefined'
    }
  };

  // URL パラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorInfo = { ...errorInfo, ...errorData };
    } catch (e) {
      console.warn('エラーパラメータの解析に失敗:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    const titleEl = container.querySelector('#error-title');
    const messageEl = container.querySelector('#error-message');
    const codeEl = container.querySelector('#error-code');
    const timestampEl = container.querySelector('#error-timestamp');
    const detailsEl = container.querySelector('#error-details');
    const networkErrorEl = container.querySelector('#network-error-message');
    const sessionErrorEl = container.querySelector('#session-error-message');

    if (titleEl) titleEl.textContent = errorInfo.title;
    if (messageEl) {
      // 長いメッセージは500文字で切り詰め
      let displayMessage = errorInfo.message;
      if (displayMessage.length > 500) {
        displayMessage = displayMessage.substring(0, 500) + '...';
      }
      messageEl.innerHTML = displayMessage.replace(/\n/g, '<br>');
    }
    if (codeEl) codeEl.textContent = errorInfo.code;
    if (timestampEl) timestampEl.textContent = errorInfo.timestamp;

    // エラー詳細の更新
    if (detailsEl && errorInfo.details) {
      const detailsContent = detailsEl.querySelector('div:last-child');
      if (detailsContent) {
        detailsContent.innerHTML = `
          <div>URL: ${errorInfo.details.url || 'N/A'}</div>
          <div>Method: ${errorInfo.details.method || 'N/A'}</div>
          <div>Status: ${errorInfo.details.status || 'N/A'}</div>
          <div>Message: ${errorInfo.details.message || 'N/A'}</div>
          <div>Stack: ${errorInfo.details.stack || 'N/A'}</div>
        `;
      }
    }

    // エラータイプ別の追加メッセージ表示
    if (networkErrorEl) {
      if (errorInfo.type === 'network') {
        networkErrorEl.classList.remove('hidden');
      } else {
        networkErrorEl.classList.add('hidden');
      }
    }

    if (sessionErrorEl) {
      if (errorInfo.type === 'session') {
        sessionErrorEl.classList.remove('hidden');
      } else {
        sessionErrorEl.classList.add('hidden');
      }
    }
  }

  // 初期表示更新
  updateErrorDisplay();

  // 再試行ボタン
  const retryBtn = container.querySelector('#btn-retry');
  let isRetrying = false;
  if (retryBtn) {
    retryBtn.addEventListener('click', async () => {
      if (isRetrying) return;

      isRetrying = true;
      retryBtn.disabled = true;
      retryBtn.textContent = '再試行中...';
      retryBtn.style.background = 'rgba(var(--primary), 0.6)';

      try {
        // ネットワーク接続チェック
        if (!navigator.onLine) {
          throw new Error('ネットワーク接続がありません');
        }

        // セッション確認（簡易チェック）
        const response = await fetch(`${apiUrl}/api/health`, { 
          method: 'GET',
          credentials: 'include'
        });

        if (response.status === 401) {
          // セッション切れ
          errorInfo.type = 'session';
          errorInfo.title = 'セッションが切れました';
          errorInfo.message = '再度ログインしてください。';
          updateErrorDisplay();
          return;
        }

        if (response.ok) {
          // 成功 - 前の画面に戻る
          if (window.history.length > 1) {
            window.history.back();
          } else {
            window.showScreen('scr-1778907133295'); // 工数記録画面
          }
        } else {
          throw new Error('サーバーエラーが継続しています');
        }
      } catch (error) {
        // 再試行失敗
        if (error.message.includes('ネットワーク')) {
          errorInfo.type = 'network';
          errorInfo.title = 'ネットワークエラー';
          errorInfo.message = '再試行に失敗しました。ネットワーク接続を確認してください。';
        } else {
          errorInfo.message = '再試行に失敗しました。問題が継続しています。';
        }
        updateErrorDisplay();
      } finally {
        isRetrying = false;
        retryBtn.disabled = false;
        retryBtn.textContent = '再試行';
        retryBtn.style.background = 'var(--primary)';
      }
    });
  }

  // 戻るボタン
  const backBtn = container.querySelector('#btn-back');
  if (backBtn) {
    backBtn.addEventListener('click', () => {
      if (errorInfo.type === 'session') {
        // セッション切れの場合はログイン画面へ
        window.location.href = './login.html';
        return;
      }

      if (window.history.length > 1) {
        window.history.back();
      } else {
        window.showScreen('scr-1778907133295'); // 工数記録画面
      }
    });

    backBtn.addEventListener('mouseenter', () => {
      backBtn.style.background = 'rgba(255,255,255,0.05)';
    });

    backBtn.addEventListener('mouseleave', () => {
      backBtn.style.background = 'transparent';
    });
  }

  // ホームに戻るボタン
  const homeBtn = container.querySelector('#btn-home');
  if (homeBtn) {
    homeBtn.addEventListener('click', () => {
      window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム）
    });

    homeBtn.addEventListener('mouseenter', () => {
      homeBtn.style.background = 'rgba(255,255,255,0.05)';
    });

    homeBtn.addEventListener('mouseleave', () => {
      homeBtn.style.background = 'transparent';
    });
  }

  // 管理者に連絡ボタン
  const contactBtn = container.querySelector('#btn-contact');
  if (contactBtn) {
    contactBtn.addEventListener('click', async () => {
      try {
        // 管理者連絡機能の利用可能性チェック
        const response = await fetch(`${apiUrl}/api/contact/available`, {
          method: 'GET',
          credentials: 'include'
        });

        if (response.ok) {
          // 緊急報告画面に遷移
          window.showScreen('scr-1778907330826');
        } else {
          throw new Error('連絡機能が利用できません');
        }
      } catch (error) {
        // 管理者連絡機能が利用できない場合
        alert('管理者連絡機能が現在利用できません。\n\n代替の連絡方法:\n電話: 03-1234-5678\nメール: admin@company.com');
      }
    });

    contactBtn.addEventListener('mouseenter', () => {
      contactBtn.style.background = 'rgba(255,255,255,0.05)';
    });

    contactBtn.addEventListener('mouseleave', () => {
      contactBtn.style.background = 'transparent';
    });
  }

  // エラー詳細表示ボタン
  const detailsBtn = container.querySelector('#btn-details');
  const detailsDiv = container.querySelector('#error-details');
  if (detailsBtn && detailsDiv) {
    detailsBtn.addEventListener('click', () => {
      try {
        if (detailsDiv.classList.contains('hidden')) {
          detailsDiv.classList.remove('hidden');
          detailsBtn.textContent = 'エラー詳細を非表示';
        } else {
          detailsDiv.classList.add('hidden');
          detailsBtn.textContent = 'エラー詳細を表示';
        }
      } catch (error) {
        // エラー詳細情報が取得できない場合
        detailsDiv.innerHTML = `
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 8px; font-weight: 600;">詳細情報:</div>
          <div style="font-size: 11px; color: var(--text);">
            エラーの詳細情報を取得できませんでした。
          </div>
        `;
        detailsDiv.classList.remove('hidden');
        detailsBtn.textContent = 'エラー詳細を非表示';
      }
    });
  }

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    if (errorInfo.type === 'network') {
      const networkErrorEl = container.querySelector('#network-error-message');
      if (networkErrorEl) {
        networkErrorEl.style.background = 'rgba(40,167,69,0.1)';
        networkErrorEl.style.borderColor = 'rgba(40,167,69,0.3)';
        networkErrorEl.textContent = 'ネットワーク接続が復旧しました。再試行してください。';
      }
    }
  });

  window.addEventListener('offline', () => {
    errorInfo.type = 'network';
    errorInfo.title = 'ネットワークエラー';
    errorInfo.message = 'インターネット接続が切断されました。';
    updateErrorDisplay();
  });

  // プライマリボタンのホバー効果
  if (retryBtn) {
    retryBtn.addEventListener('mouseenter', () => {
      if (!retryBtn.disabled) {
        retryBtn.style.background = 'var(--primary-hover)';
      }
    });

    retryBtn.addEventListener('mouseleave', () => {
      if (!retryBtn.disabled) {
        retryBtn.style.background = 'var(--primary)';
      }
    });
  }
}

function(container, apiUrl, tables) {
  let currentAnomalies = [];
  let validationInProgress = false;
  let currentEditingId = null;

  // 異常値検出結果の再描画
  function renderAnomalies(anomalies) {
    const tbody = container.querySelector('#anomaly-tbody');
    const noAnomalyMessage = container.querySelector('#no-anomaly-message');

    if (!anomalies || anomalies.length === 0) {
      tbody.innerHTML = '';
      noAnomalyMessage.style.display = 'block';
      return;
    }

    noAnomalyMessage.style.display = 'none';

    tbody.innerHTML = anomalies.map(anomaly => {
      const severityColor = anomaly.重要度 === '高' ? '#ef4444' : 
                           anomaly.重要度 === '中' ? '#f59e0b' : '#10b981';
      const statusColor = anomaly.確認状況 === '未確認' ? '#ef4444' : 
                         anomaly.確認状況 === '確認済み' ? '#f59e0b' : '#10b981';

      return `
        <tr data-id="${anomaly.異常値検出ログID || anomaly.id}" style="height: 36px;">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="anomaly-checkbox" data-id="${anomaly.異常値検出ログID || anomaly.id}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${anomaly.検出日時 ? new Date(anomaly.検出日時).toLocaleString() : ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${anomaly.作業員名 || ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${anomaly.異常値種別 || ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${anomaly.検出項目 || ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${anomaly.検出値 || ''}
          </td>
          <td style="padding: 6px 10px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${severityColor}20; color: ${severityColor}; font-weight: 500;">
              ${anomaly.重要度 || ''}
            </span>
          </td>
          <td style="padding: 6px 10px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${statusColor}20; color: ${statusColor}; font-weight: 500;">
              ${anomaly.確認状況 || ''}
            </span>
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary correction-btn" data-id="${anomaly.異常値検出ログID || anomaly.id}" style="font-size: 11px; padding: 4px 8px;">
              修正
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データの描画
  const anomalyData = tables.find(t => t.tableName === '異常値検出ログ');
  if (anomalyData) {
    currentAnomalies = anomalyData.records || [];
    renderAnomalies(currentAnomalies);
  }

  // 検証実行
  container.querySelector('#btn-execute-validation').addEventListener('click', async () => {
    if (validationInProgress) {
      showError('検証処理が実行中です。しばらくお待ちください。');
      return;
    }

    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!startDate || !endDate) {
      showError('検証対象期間を選択してください。');
      return;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を選択してください。');
      return;
    }

    validationInProgress = true;
    showProgress();
    updateStatus('検証実行中...');

    try {
      // 進捗バーのアニメーション
      let progress = 0;
      const progressInterval = setInterval(() => {
        progress += Math.random() * 15;
        if (progress > 90) progress = 90;
        updateProgressBar(progress);
      }, 200);

      // 異常値検出ログを取得
      const anomalies = await window.aivicApi.list(4); // 異常値検出ログのテーブルインデックス

      clearInterval(progressInterval);
      updateProgressBar(100);

      setTimeout(() => {
        hideProgress();
        validationInProgress = false;
        updateStatus('検証完了');
        showNotification();

        if (anomalies) {
          currentAnomalies = anomalies;
          applyFilter();
        }
      }, 500);

    } catch (error) {
      validationInProgress = false;
      hideProgress();
      updateStatus('検証エラー');
      showError('検証処理中にエラーが発生しました。');
    }
  });

  // 再検証
  container.querySelector('#btn-re-validation').addEventListener('click', () => {
    if (validationInProgress) {
      showError('検証処理が実行中です。しばらくお待ちください。');
      return;
    }

    if (confirm('再検証を実行しますか？')) {
      container.querySelector('#btn-execute-validation').click();
    }
  });

  // エラー種別フィルター
  container.querySelector('#error-type-filter').addEventListener('change', applyFilter);

  function applyFilter() {
    const filterValue = container.querySelector('#error-type-filter').value;
    let filteredAnomalies = currentAnomalies;

    if (filterValue) {
      filteredAnomalies = currentAnomalies.filter(anomaly => 
        anomaly.異常値種別 === filterValue
      );
    }

    renderAnomalies(filteredAnomalies);
  }

  // 一括承認チェックボックス
  container.querySelector('#bulk-approve-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.anomaly-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括承認実行
  container.querySelector('#btn-bulk-approve').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.anomaly-checkbox:checked');

    if (checkedBoxes.length === 0) {
      showError('承認する項目を選択してください。');
      return;
    }

    if (!confirm(`${checkedBoxes.length}件のデータを承認しますか？`)) {
      return;
    }

    try {
      for (const checkbox of checkedBoxes) {
        const id = checkbox.dataset.id;
        await window.aivicApi.update(4, id, {
          確認状況: '対応済み',
          確認日時: new Date().toISOString(),
          確認者ID: 'current-user-id'
        });
      }

      // データを再取得して表示更新
      const updatedAnomalies = await window.aivicApi.list(4);
      if (updatedAnomalies) {
        currentAnomalies = updatedAnomalies;
        applyFilter();
      }

      showSuccess(`${checkedBoxes.length}件のデータを承認しました。`);
      container.querySelector('#bulk-approve-all').checked = false;

    } catch (error) {
      showError('一括承認処理中にエラーが発生しました。');
    }
  });

  // 検証ログ出力
  container.querySelector('#btn-export-log').addEventListener('click', async () => {
    try {
      const anomalies = await window.aivicApi.list(4);

      if (!anomalies || anomalies.length === 0) {
        showError('検証結果がありません。先にデータ検証を実行してください。');
        return;
      }

      const headers = ['検出日時', '作業員名', '異常値種別', '検出項目', '検出値', '重要度', '確認状況'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...anomalies.map(anomaly => [
          anomaly.検出日時 || '',
          anomaly.作業員名 || '',
          anomaly.異常値種別 || '',
          anomaly.検出項目 || '',
          anomaly.検出値 || '',
          anomaly.重要度 || '',
          anomaly.確認状況 || ''
        ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      showError('ログ出力中にエラーが発生しました。');
    }
  });

  // 修正ボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const correctionBtn = e.target.closest('.correction-btn');
    if (correctionBtn) {
      const anomalyId = correctionBtn.dataset.id;
      const anomaly = currentAnomalies.find(a => (a.異常値検出ログID || a.id) === anomalyId);

      if (anomaly) {
        openCorrectionModal(anomaly);
      }
    }
  });

  // 修正モーダル関連
  function openCorrectionModal(anomaly) {
    currentEditingId = anomaly.検出対象レコードID;
    const modal = container.querySelector('#correction-modal');

    // 作業記録データを取得して表示
    window.aivicApi.list(1).then(workRecords => { // 作業記録のテーブルインデックス
      const workRecord = workRecords?.find(w => w.作業記録ID === anomaly.検出対象レコードID);

      if (workRecord) {
        container.querySelector('#modal-start-time').value = workRecord.作業開始時刻 ? 
          new Date(workRecord.作業開始時刻).toISOString().slice(0, 16) : '';
        container.querySelector('#modal-end-time').value = workRecord.作業終了時刻? 
          new Date(workRecord.作業終了時刻).toISOString().slice(0, 16) : '';
        container.querySelector('#modal-work-content').value = workRecord.作業内容 || '';
      }
    });

    modal.style.display = 'block';
  }

  // モーダル閉じる
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#correction-modal').style.display = 'none';
    hideModalError();
  });

  container.querySelector('#modal-cancel').addEventListener('click', () => {
    container.querySelector('#correction-modal').style.display = 'none';
    hideModalError();
  });

  // モーダル保存
  container.querySelector('#modal-save').addEventListener('click', async () => {
    const startTime = container.querySelector('#modal-start-time').value;
    const endTime = container.querySelector('#modal-end-time').value;
    const workContent = container.querySelector('#modal-work-content').value;

    // バリデーション
    if (!startTime) {
      showModalError('作業開始時刻を入力してください。');
      return;
    }

    if (!endTime) {
      showModalError('作業終了時刻を入力してください。');
      return;
    }

    if (new Date(startTime) >= new Date(endTime)) {
      showModalError('作業終了時刻は開始時刻より後の時刻を入力してください。');
      return;
    }

    if (!workContent.trim()) {
      showModalError('作業内容を入力してください。');
      return;
    }

    if (workContent.length > 1000) {
      showModalError('作業内容は1000文字以内で入力してください。');
      return;
    }

    try {
      // 作業記録を更新
      const updated = await window.aivicApi.update(1, currentEditingId, {
        作業開始時刻: new Date(startTime).toISOString(),
        作業終了時刻: new Date(endTime).toISOString(),
        作業内容: workContent,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        container.querySelector('#correction-modal').style.display = 'none';
        showSuccess('データを修正しました。');

        // 異常値検出ログを再取得
        const updatedAnomalies = await window.aivicApi.list(4);
        if (updatedAnomalies) {
          currentAnomalies = updatedAnomalies;
          applyFilter();
        }
      } else {
        showModalError('データの保存に失敗しました。');
      }

    } catch (error) {
      showModalError('修正データが不正です。入力内容を確認してください。');
    }
  });

  // ユーティリティ関数
  function showProgress() {
    container.querySelector('#progress-container').style.display = 'block';
  }

  function hideProgress() {
    container.querySelector('#progress-container').style.display = 'none';
  }

  function updateProgressBar(percentage) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    progressBar.style.width = percentage + '%';
    progressText.textContent = Math.round(percentage) + '%';
  }

  function updateStatus(message) {
    container.querySelector('#validation-status').innerHTML = 
      `<div style="font-size: 12px; color: var(--text);">${message}</div>`;
  }

  function showNotification() {
    const notification = container.querySelector('#notification-area');
    notification.style.display = 'block';
    setTimeout(() => {
      notification.style.display = 'none';
    }, 5000);
  }

  function showError(message) {
    // 簡易的なエラー表示（実際のプロジェクトでは共通のtoast機能を使用）
    alert(message);
  }

  function showSuccess(message) {
    // 簡易的な成功表示（実際のプロジェクトでは共通のtoast機能を使用）
    alert(message);
  }

  function showModalError(message) {
    const errorDiv = container.querySelector('#modal-error');
    errorDiv.querySelector('div').textContent = message;
    errorDiv.style.display = 'block';
  }

  function hideModalError() {
    container.querySelector('#modal-error').style.display = 'none';
  }
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let breakRecords = [];
  let workItems = [];
  let selectedRecord = null;

  // DOM要素取得
  const targetRecordSelect = container.querySelector('#target-record');
  const correctionForm = container.querySelector('#correction-form');
  const workDateInput = container.querySelector('#work-date');
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const workItemSelect = container.querySelector('#work-item');
  const breakTimeInput = container.querySelector('#break-time');
  const breakReasonSelect = container.querySelector('#break-reason');
  const breakDurationDiv = container.querySelector('#break-duration');
  const actualWorkTimeDiv = container.querySelector('#actual-work-time');
  const correctionReasonTextarea = container.querySelector('#correction-reason');
  const reasonCountSpan = container.querySelector('#reason-count');
  const warningArea = container.querySelector('#warning-area');
  const warningMessages = container.querySelector('#warning-messages');
  const originalDataDiv = container.querySelector('#original-data');
  const errorMessages = container.querySelector('#error-messages');
  const errorList = container.querySelector('#error-list');
  const btnSave = container.querySelector('#btn-save');
  const btnCancel = container.querySelector('#btn-cancel');

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録を読み込み
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];

      // 中断記録を読み込み
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];

      // 作業項目マスタを読み込み
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      renderTargetRecords();
      renderWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録のドロップダウンを描画
  function renderTargetRecords() {
    const options = workRecords.map(record => {
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      const projectName = record.プロジェクト名 || '';
      const workType = record.作業種別 || '';
      return `<option value="${record.作業記録ID}">${workDate} - ${projectName} (${workType})</option>`;
    }).join('');

    targetRecordSelect.innerHTML = '<option value="">記録を選択してください</option>' + options;
  }

  // 作業項目のドロップダウンを描画
  function renderWorkItems() {
    const options = workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .map(item => `<option value="${item.作業項目ID}">${item.作業項目名}</option>`)
      .join('');

    workItemSelect.innerHTML = '<option value="">作業項目を選択</option>' + options;
  }

  // 修正対象記録選択時の処理
  targetRecordSelect.addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      correctionForm.style.display = 'none';
      selectedRecord = null;
      return;
    }

    selectedRecord = workRecords.find(r => r.作業記録ID === recordId);
    if (selectedRecord) {
      populateForm(selectedRecord);
      showOriginalData(selectedRecord);
      correctionForm.style.display = 'block';
    }
  });

  // フォームに既存データを設定
  function populateForm(record) {
    const workDate = new Date(record.作業日);
    workDateInput.value = workDate.toISOString().split('T')[0];

    if (record.作業開始時刻) {
      const startTime = new Date(record.作業開始時刻);
      startTimeInput.value = startTime.toTimeString().slice(0, 5);
    }

    if (record.作業終了時刻) {
      const endTime = new Date(record.作業終了時刻);
      endTimeInput.value = endTime.toTimeString().slice(0, 5);
    }

    // 作業項目を設定（プロジェクト名から推測）
    const matchingItem = workItems.find(item => 
      item.作業項目名.includes(record.作業種別) || record.作業種別.includes(item.作業項目名)
    );
    if (matchingItem) {
      workItemSelect.value = matchingItem.作業項目ID;
    }

    // 中断記録があれば設定
    const breakRecord = breakRecords.find(br => br.作業記録ID === record.作業記録ID);
    if (breakRecord) {
      if (breakRecord.中断開始日時) {
        const breakTime = new Date(breakRecord.中断開始日時);
        breakTimeInput.value = breakTime.toTimeString().slice(0, 5);
      }
      breakReasonSelect.value = breakRecord.中断理由区分 || '';
    }

    calculateTimes();
  }

  // 修正前データ表示
  function showOriginalData(record) {
    const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
    const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '-';

    originalDataDiv.innerHTML = `
      <div><strong>作業日:</strong> ${workDate}</div>
      <div><strong>作業時間:</strong> ${startTime} ～ ${endTime} (${workTime})</div>
      <div><strong>プロジェクト:</strong> ${record.プロジェクト名 || '-'}</div>
      <div><strong>作業種別:</strong> ${record.作業種別 || '-'}</div>
      <div><strong>作業場所:</strong> ${record.作業場所 || '-'}</div>
      <div><strong>進捗状況:</strong> ${record.進捗状況 || '-'}</div>
    `;
  }

  // 時間計算
  function calculateTimes() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;
    const breakTime = breakTimeInput.value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        let breakMinutes = 0;

        if (breakTime) {
          const breakStart = new Date(`2000-01-01T${breakTime}:00`);
          if (breakStart >= start && breakStart <= end) {
            // 簡易的に30分の中断時間を設定
            breakMinutes = 30;
            breakDurationDiv.textContent = `${breakMinutes}分`;
          } else {
            breakDurationDiv.textContent = '-';
          }
        } else {
          breakDurationDiv.textContent = '-';
        }

        const actualMinutes = totalMinutes - breakMinutes;
        const hours = Math.floor(actualMinutes / 60);
        const minutes = actualMinutes % 60;
        actualWorkTimeDiv.textContent = `${hours}時間${minutes}分`;

        // 異常値チェック
        checkAnomalies(actualMinutes, startTime, endTime);
      } else {
        actualWorkTimeDiv.textContent = '-';
        breakDurationDiv.textContent = '-';
      }
    } else {
      actualWorkTimeDiv.textContent = '-';
      breakDurationDiv.textContent = '-';
    }
  }

  // 異常値チェック
  function checkAnomalies(actualMinutes, startTime, endTime) {
    const warnings = [];

    // 24時間作業チェック
    if (actualMinutes >= 1440) { // 24時間 = 1440分
      warnings.push('24時間を超える作業時間が入力されています');
    }

    // 長時間作業チェック（12時間以上）
    if (actualMinutes >= 720) {
      warnings.push('12時間を超える長時間作業が検出されました');
    }

    // 開始時刻が終了時刻より後
    if (startTime && endTime && startTime >= endTime) {
      warnings.push('開始時刻が終了時刻より後になっています');
    }

    // 中断時刻が作業時間外
    const breakTime = breakTimeInput.value;
    if (breakTime && startTime && endTime) {
      if (breakTime < startTime || breakTime > endTime) {
        warnings.push('中断時刻が作業時間外に設定されています');
      }
    }

    if (warnings.length > 0) {
      warningMessages.innerHTML = warnings.map(w => `<div>• ${w}</div>`).join('');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 修正理由文字数カウント
  correctionReasonTextarea.addEventListener('input', function() {
    reasonCountSpan.textContent = this.value.length;
  });

  // 時刻入力時の計算
  [startTimeInput, endTimeInput, breakTimeInput].forEach(input => {
    input.addEventListener('change', calculateTimes);
  });

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!targetRecordSelect.value) {
      errors.push('修正対象記録を選択してください');
    }

    if (!correctionReasonTextarea.value.trim()) {
      errors.push('修正理由を入力してください');
    }

    const workDate = workDateInput.value;
    if (workDate) {
      const date = new Date(workDate);
      const minDate = new Date('1900-01-01');
      const maxDate = new Date('2099-12-31');
      const today = new Date();

      if (date < minDate || date > maxDate) {
        errors.push('作業日付は1900年1月1日から2099年12月31日の範囲で入力してください');
      }
    }

    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;

    if (startTime && endTime && startTime >= endTime) {
      errors.push('開始時刻は終了時刻より前の時刻を入力してください');
    }

    return errors;
  }

  // エラー表示
  function showErrors(errors) {
    if (errors.length > 0) {
      errorList.innerHTML = errors.map(error => `<div>• ${error}</div>`).join('');
      errorMessages.style.display = 'block';
    } else {
      errorMessages.style.display = 'none';
    }
  }

  // 保存処理
  btnSave.addEventListener('click', async function() {
    const errors = validateForm();
    showErrors(errors);

    if (errors.length > 0) {
      return;
    }

    try {
      // 作業記録の更新
      const updatedRecord = {
        ...selectedRecord,
        作業日: new Date(workDateInput.value).toISOString(),
        作業開始時刻: workDateInput.value && startTimeInput.value ? 
          new Date(`${workDateInput.value}T${startTimeInput.value}:00`).toISOString() : selectedRecord.作業開始時刻,
        作業終了時刻: workDateInput.value && endTimeInput.value ? 
          new Date(`${workDateInput.value}T${endTimeInput.value}:00`).toISOString() : selectedRecord.作業終了時刻,
        更新日時: new Date().toISOString()
      };

      // 実作業時間を計算して更新
      if (startTimeInput.value && endTimeInput.value) {
        const start = new Date(`2000-01-01T${startTimeInput.value}:00`);
        const end = new Date(`2000-01-01T${endTimeInput.value}:00`);
        const totalMinutes = (end - start) / (1000 * 60);
        const breakMinutes = breakTimeInput.value ? 30 : 0; // 簡易的に30分
        updatedRecord.作業時間 = totalMinutes - breakMinutes;
      }

      await window.aivicApi.update(1, selectedRecord.作業記録ID, updatedRecord);

      // 中断記録の更新（存在する場合）
      if (breakTimeInput.value || breakReasonSelect.value) {
        const existingBreakRecord = breakRecords.find(br => br.作業記録ID === selectedRecord.作業記録ID);

        const breakRecordData = {
          作業記録ID: selectedRecord.作業記録ID,
          中断開始日時: workDateInput.value && breakTimeInput.value ? 
            new Date(`${workDateInput.value}T${breakTimeInput.value}:00`).toISOString() : null,
          中断理由区分: breakReasonSelect.value,
          中断時間: breakTimeInput.value ? 30 : null, // 簡易的に30分
          対応状況: '対応済み',
          記録者ID: selectedRecord.作業員ID,
          更新日時: new Date().toISOString()
        };

        if (existingBreakRecord) {
          await window.aivicApi.update(2, existingBreakRecord.中断記録ID, breakRecordData);
        } else if (breakTimeInput.value || breakReasonSelect.value) {
          breakRecordData.中断記録ID = crypto.randomUUID();
          breakRecordData.作成日時 = new Date().toISOString();
          await window.aivicApi.save(2, breakRecordData);
        }
      }

      alert('修正が正常に保存されました');

      // フォームをリセット
      targetRecordSelect.value = '';
      correctionForm.style.display = 'none';
      correctionReasonTextarea.value = '';
      reasonCountSpan.textContent = '0';
      selectedRecord = null;

      // データを再読み込み
      await loadInitialData();

    } catch (error) {
      console.error('保存エラー:', error);
      showErrors(['保存中にエラーが発生しました']);
    }
  });

  // キャンセル処理
  btnCancel.addEventListener('click', function() {
    if (confirm('修正内容を破棄しますか？')) {
      targetRecordSelect.value = '';
      correctionForm.style.display = 'none';
      correctionReasonTextarea.value = '';
      reasonCountSpan.textContent = '0';
      selectedRecord = null;
      errorMessages.style.display = 'none';
      warningArea.style.display = 'none';
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let attachedFiles = [];
  let currentUser = null;

  // 現在のユーザー情報を取得（報告者名の自動入力用）
  async function loadCurrentUser() {
    try {
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (users && users.length > 0) {
        currentUser = users[0]; // 最初のユーザーを現在のユーザーとして使用
        container.querySelector('#reporter-name').value = currentUser.氏名 || '';
      }
    } catch (error) {
      console.error('ユーザー情報の取得に失敗しました:', error);
    }
  }

  // 作業項目の読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      const select = container.querySelector('#work-item');
      if (workItems) {
        workItems.filter(item => item.有効フラグ).forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = item.作業項目名;
          select.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の取得に失敗しました:', error);
    }
  }

  // 緊急度ボタンの処理
  container.querySelectorAll('.urgency-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      // 全ボタンのスタイルをリセット
      container.querySelectorAll('.urgency-btn').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = 'var(--text)';
      });

      // 選択されたボタンをハイライト
      btn.style.background = 'var(--primary)';
      btn.style.color = '#fff';
      selectedUrgency = btn.dataset.value;

      // エラーメッセージをクリア
      container.querySelector('#urgency-error').style.display = 'none';
    });
  });

  // 文字数カウンター
  const contentTextarea = container.querySelector('#emergency-content');
  const charCount = container.querySelector('#char-count');
  contentTextarea.addEventListener('input', () => {
    const length = contentTextarea.value.length;
    charCount.textContent = `${length}/1000`;
    if (length > 1000) {
      charCount.style.color = '#ff6a6a';
      container.querySelector('#content-error').textContent = '文字数上限を超えています';
      container.querySelector('#content-error').style.display = 'block';
    } else {
      charCount.style.color = 'var(--text-muted)';
      container.querySelector('#content-error').style.display = 'none';
    }
  });

  // ファイル添付の処理
  const fileInput = container.querySelector('#photo-input');
  const dropZone = container.querySelector('#file-drop-zone');
  const imagePreview = container.querySelector('#image-preview');
  const fileError = container.querySelector('#file-error');

  dropZone.addEventListener('click', () => fileInput.click());

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
  });

  dropZone.addEventListener('dragleave', () => {
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    handleFiles(e.dataTransfer.files);
  });

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  function handleFiles(files) {
    fileError.style.display = 'none';

    // ファイル数チェック
    if (attachedFiles.length + files.length > 5) {
      fileError.textContent = '添付できる画像は最大5枚です';
      fileError.style.display = 'block';
      return;
    }

    Array.from(files).forEach(file => {
      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        fileError.textContent = 'サポートされていないファイル形式です。jpg、png形式のファイルをアップロードしてください。';
        fileError.style.display = 'block';
        return;
      }

      // ファイルサイズチェック（5MB）
      if (file.size > 5 * 1024 * 1024) {
        fileError.textContent = 'ファイルサイズは5MB以下にしてください';
        fileError.style.display = 'block';
        return;
      }

      attachedFiles.push(file);

      // プレビュー表示
      const reader = new FileReader();
      reader.onload = (e) => {
        const preview = document.createElement('div');
        preview.style.cssText = 'position: relative; width: 80px; height: 80px; border-radius: 6px; overflow: hidden; border: 1px solid rgba(255,255,255,0.18);';
        preview.innerHTML = `
          <img src="${e.target.result}" style="width: 100%; height: 100%; object-fit: cover;">
          <button type="button" class="remove-image" data-index="${attachedFiles.length - 1}" style="position: absolute; top: 2px; right: 2px; width: 20px; height: 20px; border-radius: 50%; background: rgba(0,0,0,0.7); color: #fff; border: none; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
        `;
        imagePreview.appendChild(preview);
      };
      reader.readAsDataURL(file);
    });
  }

  // 画像削除
  imagePreview.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-image')) {
      const index = parseInt(e.target.dataset.index);
      attachedFiles.splice(index, 1);
      e.target.closest('div').remove();

      // インデックスを再設定
      imagePreview.querySelectorAll('.remove-image').forEach((btn, i) => {
        btn.dataset.index = i;
      });
    }
  });

  // バリデーション関数
  function validateForm() {
    let isValid = true;

    // エラーメッセージをクリア
    container.querySelectorAll('.error-message').forEach(el => el.style.display = 'none');

    // 緊急度チェック
    if (!selectedUrgency) {
      container.querySelector('#urgency-error').textContent = '緊急度を選択してください';
      container.querySelector('#urgency-error').style.display = 'block';
      isValid = false;
    }

    // 報告種別チェック
    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      container.querySelector('#report-type-error').textContent = '報告種別を選択してください';
      container.querySelector('#report-type-error').style.display = 'block';
      isValid = false;
    }

    // 発生日時チェック
    const datetime = container.querySelector('#occurrence-datetime').value;
    if (!datetime) {
      container.querySelector('#datetime-error').textContent = '発生日時を入力してください';
      container.querySelector('#datetime-error').style.display = 'block';
      isValid = false;
    } else {
      const selectedDate = new Date(datetime);
      const now = new Date();
      if (selectedDate > now) {
        container.querySelector('#datetime-error').textContent = '発生日時に未来の日付は入力できません';
        container.querySelector('#datetime-error').style.display = 'block';
        isValid = false;
      }
    }

    // 発生場所チェック
    const location = container.querySelector('#occurrence-location').value.trim();
    if (!location) {
      container.querySelector('#location-error').textContent = '発生場所を入力してください';
      container.querySelector('#location-error').style.display = 'block';
      isValid = false;
    }

    // 緊急事態内容チェック
    const content = container.querySelector('#emergency-content').value.trim();
    if (!content) {
      container.querySelector('#content-error').textContent = '緊急事態内容を入力してください';
      container.querySelector('#content-error').style.display = 'block';
      isValid = false;
    } else if (content.length > 1000) {
      container.querySelector('#content-error').textContent = '文字数上限を超えています';
      container.querySelector('#content-error').style.display = 'block';
      isValid = false;
    }

    // 連絡先電話番号チェック
    const phone = container.querySelector('#contact-phone').value.trim();
    if (!phone) {
      container.querySelector('#phone-error').textContent = '連絡先電話番号を入力してください';
      container.querySelector('#phone-error').style.display = 'block';
      isValid = false;
    } else {
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(phone)) {
        container.querySelector('#phone-error').textContent = '正しい電話番号の形式で入力してください';
        container.querySelector('#phone-error').style.display = 'block';
        isValid = false;
      }
    }

    return isValid;
  }

  // 成功メッセージ表示
  function showSuccessMessage(message) {
    const successEl = container.querySelector('#success-message');
    successEl.textContent = message;
    successEl.style.display = 'block';
    setTimeout(() => {
      successEl.style.display = 'none';
    }, 5000);
  }

  // 緊急報告送信
  container.querySelector('#submit-btn').addEventListener('click', async () => {
    if (!validateForm()) return;

    try {
      const reportData = {
        緊急度: selectedUrgency,
        報告種別: container.querySelector('#report-type').value,
        発生日時: container.querySelector('#occurrence-datetime').value,
        発生場所: container.querySelector('#occurrence-location').value,
        作業項目ID: container.querySelector('#work-item').value || null,
        緊急事態内容: container.querySelector('#emergency-content').value,
        報告者ID: currentUser?.ユーザーID || null,
        連絡先電話番号: container.querySelector('#contact-phone').value,
        添付ファイル数: attachedFiles.length,
        報告日時: new Date().toISOString(),
        状態: '送信済み'
      };

      // 異常値検出ログテーブルに保存（緊急度が高の場合）
      const saved = await window.aivicApi.save(4, reportData);

      if (saved) {
        showSuccessMessage('緊急報告が正常に送信されました。関係者に通知が送られます。');

        // フォームをリセット
        container.querySelector('#emergency-form').reset();
        selectedUrgency = '';
        attachedFiles = [];
        imagePreview.innerHTML = '';
        container.querySelectorAll('.urgency-btn').forEach(btn => {
          btn.style.background = 'transparent';
          btn.style.color = 'var(--text)';
        });
        charCount.textContent = '0/1000';

        // 報告者名を再設定
        if (currentUser) {
          container.querySelector('#reporter-name').value = currentUser.氏名 || '';
        }
      }
    } catch (error) {
      console.error('緊急報告の送信に失敗しました:', error);
    }
  });

  // 下書き保存
  container.querySelector('#draft-btn').addEventListener('click', async () => {
    try {
      const draftData = {
        緊急度: selectedUrgency,
        報告種別: container.querySelector('#report-type').value,
        発生日時: container.querySelector('#occurrence-datetime').value,
        発生場所: container.querySelector('#occurrence-location').value,
        作業項目ID: container.querySelector('#work-item').value || null,
        緊急事態内容: container.querySelector('#emergency-content').value,
        報告者ID: currentUser?.ユーザーID || null,
        連絡先電話番号: container.querySelector('#contact-phone').value,
        添付ファイル数: attachedFiles.length,
        報告日時: new Date().toISOString(),
        状態: '下書き'
      };

      const saved = await window.aivicApi.save(4, draftData);

      if (saved) {
        showSuccessMessage('下書きが正常に保存されました。');
      }
    } catch (error) {
      console.error('下書きの保存に失敗しました:', error);
    }
  });

  // 報告完了ボタン
  container.querySelector('#complete-btn').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // ボタンホバー効果
  container.querySelector('#submit-btn').addEventListener('mouseenter', (e) => {
    e.target.style.background = 'var(--primary-hover)';
  });
  container.querySelector('#submit-btn').addEventListener('mouseleave', (e) => {
    e.target.style.background = 'var(--primary)';
  });

  container.querySelectorAll('button[style*="transparent"]').forEach(btn => {
    btn.addEventListener('mouseenter', (e) => {
      e.target.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', (e) => {
      e.target.style.background = 'transparent';
    });
  });

  // 初期化処理
  loadCurrentUser();
  loadWorkItems();

  // 現在日時を発生日時のデフォルト値として設定
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector('#occurrence-datetime').value = localDateTime;
}

function(container, apiUrl, tables) {
  let currentRecord = null;
  let originalData = null;
  let workItems = [];

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const select = container.querySelector("#select-work-item");
      select.innerHTML = '<option value="">選択してください</option>' + 
        workItems.map(item => `<option value="${item.作業項目ID}">${item.作業項目名}</option>`).join("");
    }
  }

  // 作業記録一覧を読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const select = container.querySelector("#select-work-record");
      select.innerHTML = '<option value="">選択してください</option>' + 
        records.map(record => {
          const date = new Date(record.作業日).toLocaleDateString();
          const project = record.プロジェクト名 || '';
          const workType = record.作業種別 || '';
          return `<option value="${record.作業記録ID}">${date} - ${project} - ${workType}</option>`;
        }).join("");
    }
  }

  // 時間計算
  function calculateTime() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);

      // 24時間跨ぎの場合
      if (end < start) {
        end.setDate(end.getDate() + 1);
      }

      const diffMs = end - start;
      const totalMinutes = Math.floor(diffMs / (1000 * 60));
      const netMinutes = Math.max(0, totalMinutes - breakTime);

      const totalHours = Math.floor(totalMinutes / 60);
      const totalMins = totalMinutes % 60;
      const netHours = Math.floor(netMinutes / 60);
      const netMins = netMinutes % 60;

      container.querySelector("#display-total-time").value = `${totalHours}時間${totalMins}分`;
      container.querySelector("#display-net-time").value = `${netHours}時間${netMins}分`;

      validateTime(startTime, endTime, breakTime, totalMinutes);
    } else {
      container.querySelector("#display-total-time").value = "";
      container.querySelector("#display-net-time").value = "";
    }
  }

  // バリデーション
  function validateTime(startTime, endTime, breakTime, totalMinutes) {
    const warningArea = container.querySelector("#warning-area");
    const errorArea = container.querySelector("#error-area");

    warningArea.style.display = "none";
    errorArea.style.display = "none";

    // 異常値チェック
    if (totalMinutes > 12 * 60) { // 12時間超過
      warningArea.textContent = "作業時間が12時間を超えています。確認してください。";
      warningArea.style.display = "block";
    }

    if (totalMinutes === 0) {
      errorArea.textContent = "作業時間が0分です。開始時刻と終了時刻を確認してください。";
      errorArea.style.display = "block";
    }

    if (breakTime > totalMinutes) {
      errorArea.textContent = "中断時間が作業時間を超過しています。";
      errorArea.style.display = "block";
    }
  }

  // 作業記録選択時の処理
  container.querySelector("#select-work-record").addEventListener("change", async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      originalData = null;
      clearForm();
      return;
    }

    const records = await window.aivicApi.list(1);
    if (records) {
      currentRecord = records.find(r => r.作業記録ID === recordId);
      originalData = { ...currentRecord };

      if (currentRecord) {
        // フォームに値を設定
        const workDate = new Date(currentRecord.作業日).toLocaleDateString();
        container.querySelector("#input-work-date").value = workDate;

        const startTime = new Date(currentRecord.作業開始時刻);
        const endTime = currentRecord.作業終了時刻? new Date(currentRecord.作業終了時刻) : null;

        container.querySelector("#input-start-time").value = startTime.toTimeString().slice(0, 5);
        if (endTime) {
          container.querySelector("#input-end-time").value = endTime.toTimeString().slice(0, 5);
        }

        // 中断時間を計算（中断記録から）
        const breakRecords = await window.aivicApi.list(2);
        let totalBreakTime = 0;
        if (breakRecords) {
          breakRecords.filter(br => br.作業記録ID === recordId).forEach(br => {
            totalBreakTime += br.中断時間 || 0;
          });
        }
        container.querySelector("#input-break-time").value = totalBreakTime;

        container.querySelector("#textarea-work-detail").value = currentRecord.作業内容 || "";

        // 作業項目を設定（作業種別から推測）
        const matchingItem = workItems.find(item => item.作業項目名 === currentRecord.作業種別);
        if (matchingItem) {
          container.querySelector("#select-work-item").value = matchingItem.作業項目ID;
        }

        calculateTime();
      }
    }
  });

  function clearForm() {
    container.querySelector("#input-work-date").value = "";
    container.querySelector("#input-start-time").value = "";
    container.querySelector("#input-end-time").value = "";
    container.querySelector("#input-break-time").value = "";
    container.querySelector("#display-total-time").value = "";
    container.querySelector("#display-net-time").value = "";
    container.querySelector("#select-work-item").value = "";
    container.querySelector("#textarea-work-detail").value = "";
    container.querySelector("#input-correction-reason").value = "";
    container.querySelector("#warning-area").style.display = "none";
    container.querySelector("#error-area").style.display = "none";
  }

  // 時間入力時の計算
  container.querySelector("#input-start-time").addEventListener("change", calculateTime);
  container.querySelector("#input-end-time").addEventListener("change", calculateTime);
  container.querySelector("#input-break-time").addEventListener("input", calculateTime);

  // 元データ参照
  container.querySelector("#btn-view-original").addEventListener("click", function() {
    if (!originalData) {
      alert("修正対象の作業記録を選択してください。");
      return;
    }

    const modal = container.querySelector("#modal-original-data");
    const content = container.querySelector("#original-data-content");

    const startTime = new Date(originalData.作業開始時刻).toLocaleString();
    const endTime = originalData.作業終了時刻? new Date(originalData.作業終了時刻).toLocaleString() : "未設定";

    content.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${new Date(originalData.作業日).toLocaleDateString()}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト:</strong> ${originalData.プロジェクト名 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>作業場所:</strong> ${originalData.作業場所 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${originalData.作業種別 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>作業内容:</strong> ${originalData.作業内容 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${originalData.進捗状況 || ""}</div>
    `;

    modal.style.display = "flex";
  });

  container.querySelector("#btn-close-modal").addEventListener("click", function() {
    container.querySelector("#modal-original-data").style.display = "none";
  });

  // 保存処理
  container.querySelector("#btn-save").addEventListener("click", async function() {
    const errorArea = container.querySelector("#error-area");
    errorArea.style.display = "none";

    if (!currentRecord) {
      errorArea.textContent = "修正対象の作業記録を選択してください。";
      errorArea.style.display = "block";
      return;
    }

    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;
    const correctionReason = container.querySelector("#input-correction-reason").value.trim();
    const workDetail = container.querySelector("#textarea-work-detail").value.trim();

    // バリデーション
    if (!startTime || !endTime) {
      errorArea.textContent = "作業開始時刻と終了時刻を入力してください。";
      errorArea.style.display = "block";
      return;
    }

    if (!correctionReason) {
      errorArea.textContent = "修正理由を入力してください。";
      errorArea.style.display = "block";
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = Math.floor((end - start) / (1000 * 60));

    if (totalMinutes === 0) {
      errorArea.textContent = "作業時間が0分です。開始時刻と終了時刻を確認してください。";
      errorArea.style.display = "block";
      return;
    }

    if (breakTime > totalMinutes) {
      errorArea.textContent = "中断時間が作業時間を超過しています。";
      errorArea.style.display = "block";
      return;
    }

    // 作業記録を更新
    const workDate = new Date(currentRecord.作業日);
    const newStartTime = new Date(workDate);
    newStartTime.setHours(parseInt(startTime.split(':')[0]), parseInt(startTime.split(':')[1]), 0, 0);

    const newEndTime = new Date(workDate);
    newEndTime.setHours(parseInt(endTime.split(':')[0]), parseInt(endTime.split(':')[1]), 0, 0);
    if (newEndTime < newStartTime) {
      newEndTime.setDate(newEndTime.getDate() + 1);
    }

    const updateData = {
      作業開始時刻: newStartTime.toISOString(),
      作業終了時刻: newEndTime.toISOString(),
      作業時間: totalMinutes - breakTime,
      作業内容: workDetail,
      備考: `${currentRecord.備考 || ""}\n[修正] ${correctionReason}`.trim(),
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);
    if (updated) {
      // 異常値検出ログを作成
      if (totalMinutes > 12 * 60) {
        await window.aivicApi.save(4, {
          異常値検出ログID: crypto.randomUUID(),
          検出対象テーブル: "作業記録",
          検出対象レコードID: currentRecord.作業記録ID,
          ユーザーID: currentRecord.作業員ID,
          異常値種別: "長時間作業",
          検出項目: "作業時間",
          検出値: `${Math.floor(totalMinutes/60)}時間${totalMinutes%60}分`,
          閾値: "12時間",
          重要度: "中",
          確認状況: "未確認",
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        });
      }

      alert("工数修正が完了しました。");
      window.showScreen("scr-1778907367889");
    }
  });

  // キャンセル
  container.querySelector("#btn-cancel").addEventListener("click", function() {
    window.showScreen("scr-1778907367889");
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#record-tbody");
  const emptyMessage = container.querySelector("#empty-message");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // 異常値検出関数
  function detectAnomalies(record) {
    const warnings = [];

    if (record.作業時間 && record.作業時間 > 1440) { // 24時間 = 1440分
      warnings.push("24時間を超える作業時間");
    }

    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end <= start) {
        warnings.push("終了時刻が開始時刻より早い");
      }
    }

    // 中断時間の合計を計算（中断記録テーブルから）
    const breakRecords = tables[2]?.records?.filter(br => br.作業記録ID === record.作業記録ID) || [];
    const totalBreakTime = breakRecords.reduce((sum, br) => sum + (br.中断時間 || 0), 0);

    if (totalBreakTime > record.作業時間) {
      warnings.push("中断時間が実働時間を超える");
    }

    return warnings;
  }

  // 時間フォーマット関数
  function formatTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateTime) {
    if (!dateTime) return "-";
    const date = new Date(dateTime);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(dateTime) {
    if (!dateTime) return "-";
    const date = new Date(dateTime);
    return date.toLocaleDateString('ja-JP');
  }

  // 承認状態バッジ
  function getStatusBadge(status) {
    const colors = {
      '未承認': 'background: rgba(255, 193, 7, 0.2); color: #856404; border: 1px solid rgba(255, 193, 7, 0.3);',
      '承認済み': 'background: rgba(40, 167, 69, 0.2); color: #155724; border: 1px solid rgba(40, 167, 69, 0.3);',
      '差し戻し': 'background: rgba(220, 53, 69, 0.2); color: #721c24; border: 1px solid rgba(220, 53, 69, 0.3);'
    };
    const style = colors[status] || colors['未承認'];
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${style}">${status || '未承認'}</span>`;
  }

  // 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      emptyMessage.classList.remove("hidden");
      return;
    }

    emptyMessage.classList.add("hidden");

    // ユーザー情報を取得
    const users = tables[0]?.records || [];

    tbody.innerHTML = rows.map(record => {
      const user = users.find(u => u.ユーザーID === record.作業員ID);
      const warnings = detectAnomalies(record);
      const warningIcon = warnings.length > 0 ? 
        `<span title="${warnings.join(', ')}" style="color: #ff6b35; margin-left: 4px; cursor: help;">⚠️</span>` : '';

      const isApproved = record.承認状態 === '承認済み';
      const canEdit = !isApproved; // 承認済みは編集不可
      const canApprove = record.承認状態 === '未承認'; // 未承認のみ承認可能

      return `
        <tr data-id="${record.作業記録ID}" style="height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatDate(record.作業日)}${warningIcon}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
