          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatDateTime(record.作業開始時刻)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatDateTime(record.作業終了時刻)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatTime(record.作業時間)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${formatTime(record.中断時間合計 || 0)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
            ${record.作業内容 || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${record.作業場所 || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            ${getStatusBadge(record.承認状態)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.02);">
            <button class="detail-btn" data-id="${record.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細</button>
            ${canEdit ? `<button class="edit-btn" data-id="${record.作業記録ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">修正</button>` : ''}
            ${canApprove ? `<button class="approve-btn" data-id="${record.作業記録ID}" style="background: #28a745; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">承認</button>` : ''}
            <button class="delete-btn" data-id="${record.作業記録ID}" style="background: #dc3545; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細表示関数
  function showDetail(recordId) {
    const records = tables[1]?.records || [];
    const users = tables[0]?.records || [];
    const breakRecords = tables[2]?.records || [];

    const record = records.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const user = users.find(u => u.ユーザーID === record.作業員ID);
    const breaks = breakRecords.filter(br => br.作業記録ID === recordId);
    const warnings = detectAnomalies(record);

    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px;">
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業日</label>
          <div style="font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業者</label>
          <div style="font-size: 13px; color: var(--text);">${user?.氏名 || '-'}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">開始時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatDateTime(record.作業開始時刻)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">終了時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatDateTime(record.作業終了時刻)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業時間)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">プロジェクト</label>
          <div style="font-size: 13px; color: var(--text);">${record.プロジェクト名 || '-'}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業場所</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業場所 || '-'}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業種別</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業種別 || '-'}</div>
        </div>
      </div>

      <div style="margin-bottom: 16px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業内容</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px; min-height: 60px;">
          ${record.作業内容 || '-'}
        </div>
      </div>

      ${record.備考 ? `
        <div style="margin-bottom: 16px;">
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">備考</label>
          <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px;">
            ${record.備考}
          </div>
        </div>
      ` : ''}

      ${breaks.length > 0 ? `
        <div style="margin-bottom: 16px;">
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 8px;">中断記録</label>
          ${breaks.map(br => `
            <div style="padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px; margin-bottom: 4px;">
              <div style="font-size: 12px; color: var(--text);">
                ${formatDateTime(br.中断開始日時)} - ${formatDateTime(br.中断終了日時)} 
                (${formatTime(br.中断時間)})
              </div>
              <div style="font-size: 11px; color: var(--text-muted);">
                理由: ${br.中断理由区分} ${br.中断理由詳細 ? `- ${br.中断理由詳細}` : ''}
              </div>
            </div>
          `).join('')}
        </div>
      ` : ''}

      ${warnings.length > 0 ? `
        <div style="margin-bottom: 16px; padding: 8px; background: rgba(255, 107, 53, 0.1); border: 1px solid rgba(255, 107, 53, 0.3); border-radius: 4px;">
          <div style="font-size: 12px; font-weight: 600; color: #ff6b35; margin-bottom: 4px;">⚠️ 異常値検出</div>
          ${warnings.map(w => `<div style="font-size: 11px; color: #ff6b35;">• ${w}</div>`).join('')}
        </div>
      ` : ''}

      <div style="display: flex; justify-content: space-between; align-items: center;">
        <div>
          <span style="font-size: 11px; color: var(--text-muted);">承認状態: </span>
          ${getStatusBadge(record.承認状態)}
        </div>
        <div style="display: flex; gap: 8px;">
          ${record.承認状態 !== '承認済み' ? `<button class="edit-btn" data-id="${record.作業記録ID}" style="background: var(--primary); color: #fff; border: none; padding: 6px 14px; border-radius: 6px; font-size: 13px; cursor: pointer;">修正</button>` : ''}
          ${record.承認状態 === '未承認' ? `<button class="approve-btn" data-id="${record.作業記録ID}" style="background: #28a745; color: #fff; border: none; padding: 6px 14px; border-radius: 6px; font-size: 13px; cursor: pointer;">承認</button>` : ''}
        </div>
      </div>
    `;

    detailModal.classList.remove("hidden");
  }

  // CSVエクスポート関数
  function exportCSV() {
    window.aivicApi.list(1).then(rows => {
      if (!rows || rows.length === 0) {
        alert("エクスポートするデータがありません");
        return;
      }

      const users = tables[0]?.records || [];
      const headers = ["作業日", "作業者", "開始時刻", "終了時刻", "作業時間", "プロジェクト名", "作業場所", "作業種別", "作業内容", "承認状態"];

      const csvData = [
        headers.join(","),
        ...rows.map(record => {
          const user = users.find(u => u.ユーザーID === record.作業員ID);
          return [
            formatDate(record.作業日),
            user?.氏名 || '',
            formatDateTime(record.作業開始時刻),
            formatDateTime(record.作業終了時刻),
            formatTime(record.作業時間),
            record.プロジェクト名 || '',
            record.作業場所 || '',
            record.作業種別 || '',
            `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
            record.承認状態 || ''
          ].join(",");
        })
      ].join("\n");

      const bom = "\uFEFF";
      const blob = new Blob([bom + csvData], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      renderRows(rows);
    }
  });

  // 絞り込み検索
  container.querySelector("#btn-search").addEventListener("click", () => {
    const dateFilter = container.querySelector("#date-filter").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    // 日付検証
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を指定してください");
      return;
    }

    window.aivicApi.list(1).then(rows => {
      if (!rows) return;

      let filtered = rows;

      if (dateFilter) {
        filtered = filtered.filter(r => {
          const recordDate = new Date(r.作業日).toISOString().split('T')[0];
          return recordDate === dateFilter;
        });
      }

      if (startDate) {
        filtered = filtered.filter(r => {
          const recordDate = new Date(r.作業日).toISOString().split('T')[0];
          return recordDate >= startDate;
        });
      }

      if (endDate) {
        filtered = filtered.filter(r => {
          const recordDate = new Date(r.作業日).toISOString().split('T')[0];
          return recordDate <= endDate;
        });
      }

      renderRows(filtered);
    });
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 詳細モーダル閉じる
  container.querySelector("#close-detail").addEventListener("click", () => {
    detailModal.classList.add("hidden");
  });

  // モーダル背景クリックで閉じる
  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.classList.add("hidden");
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 編集
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      window.showScreen("scr-1778907343735");
      return;
    }

    // 承認
    const approveBtn = e.target.closest(".approve-btn");
    if (approveBtn) {
      if (!confirm("この工数記録を承認しますか？")) return;

      const updated = await window.aivicApi.update(1, approveBtn.dataset.id, {
        承認状態: "承認済み",
        承認者ID: "current-user-id", // 実際の実装では現在のユーザーIDを使用
        承認日時: new Date().toISOString()
      });

      if (updated) {
        alert("承認が完了しました");
        window.aivicApi.list(1).then(renderRows);
      }
      return;
    }

    // 削除
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      const record = tables[1]?.records?.find(r => r.作業記録ID === deleteBtn.dataset.id);

      if (record?.承認状態 === '承認済み') {
        alert("承認済みの記録は削除できません");
        return;
      }

      if (!confirm("この工数記録を削除しますか？")) return;

      await window.aivicApi.delete(1, deleteBtn.dataset.id);
      window.aivicApi.list(1).then(renderRows);
      return;
    }
  });
}

function(container, apiUrl, tables) {
  // 現在のユーザー情報を設定
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;
  container.querySelector('#work-date').max = today;

  let breakRecords = [];

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">選択してください</option>';
    if (workItems) {
      workItems.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    }
  }

  // 工数計算
  function calculateHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakMinutes = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#calculated-hours').textContent = '0.0h';
      return 0;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      end.setDate(end.getDate() + 1); // 日付跨ぎ対応
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const breakTotal = breakRecords.reduce((sum, br) => sum + (br.中断時間 || 0), 0) + breakMinutes;
    const workMinutes = Math.max(0, totalMinutes - breakTotal);
    const hours = (workMinutes / 60).toFixed(1);

    container.querySelector('#calculated-hours').textContent = `${hours}h`;
    return workMinutes;
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#work-details');
    const count = textarea.value.length;
    container.querySelector('#char-count').textContent = count;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="background: rgba(220, 38, 38, 0.1); border: 1px solid rgba(220, 38, 38, 0.3); border-radius: 6px; padding: 8px; color: #dc2626; font-size: 13px; margin-bottom: 8px;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = '', 5000);
  }

  // 成功表示
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); border-radius: 6px; padding: 8px; color: #22c55e; font-size: 13px; margin-bottom: 8px;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = '', 3000);
  }

  // バリデーション
  function validateForm() {
    const workDate = container.querySelector('#work-date').value;
    const projectName = container.querySelector('#project-name').value;
    const workItem = container.querySelector('#work-item').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workLocation = container.querySelector('#work-location').value;
    const workDetails = container.querySelector('#work-details').value;
    const breakMinutes = parseInt(container.querySelector('#break-time').value) || 0;

    if (!workDate) {
      showError('作業日を入力してください');
      return false;
    }

    if (new Date(workDate) > new Date(today)) {
      showError('未来日付は選択できません');
      return false;
    }

    if (!projectName) {
      showError('プロジェクト名を選択してください');
      return false;
    }

    if (!workItem) {
      showError('作業項目を選択してください');
      return false;
    }

    if (!startTime) {
      showError('開始時刻を入力してください');
      return false;
    }

    if (!endTime) {
      showError('終了時刻を入力してください');
      return false;
    }

    if (!workLocation) {
      showError('作業場所を選択してください');
      return false;
    }

    if (!workDetails.trim()) {
      showError('作業内容詳細を入力してください');
      return false;
    }

    if (workDetails.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください');
      return false;
    }

    // 時刻チェック
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    let totalMinutes = (end - start) / (1000 * 60);

    if (totalMinutes <= 0) {
      end.setDate(end.getDate() + 1);
      totalMinutes = (end - start) / (1000 * 60);
    }

    if (totalMinutes >= 24 * 60) {
      showError('24時間以上の作業時間は入力できません');
      return false;
    }

    const breakTotal = breakRecords.reduce((sum, br) => sum + (br.中断時間 || 0), 0) + breakMinutes;
    if (breakTotal >= totalMinutes) {
      showError('中断時間は作業時間を超過できません');
      return false;
    }

    return true;
  }

  // フォームクリア
  function clearForm() {
    container.querySelector('#work-date').value = today;
    container.querySelector('#project-name').value = '';
    container.querySelector('#work-item').value = '';
    container.querySelector('#start-time').value = '';
    container.querySelector('#end-time').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#work-details').value = '';
    container.querySelector('#break-time').value = '0';
    breakRecords = [];
    container.querySelector('#break-records').innerHTML = '';
    updateCharCount();
    calculateHours();
    container.querySelector('#error-messages').innerHTML = '';
  }

  // 中断記録追加
  function addBreakRecord() {
    window.showScreen('scr-1778907238439'); // 中断記録入力画面
  }

  // 保存処理
  async function saveRecord(isTemp = false) {
    if (!validateForm()) return;

    const workMinutes = calculateHours();
    const formData = {
      作業員ID: currentUser.id,
      作業日: new Date(container.querySelector('#work-date').value + 'T00:00:00'),
      作業開始時刻: new Date(container.querySelector('#work-date').value + 'T' + container.querySelector('#start-time').value),
      作業終了時刻: new Date(container.querySelector('#work-date').value + 'T' + container.querySelector('#end-time').value),
      作業時間: Math.round(workMinutes),
      プロジェクト名: container.querySelector('#project-name').value,
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item option:checked')?.textContent?.split(' - ')[1] || '',
      作業内容: container.querySelector('#work-details').value,
      進捗状況: isTemp ? '一時保存' : '完了',
      備考: `休憩時間: ${container.querySelector('#break-time').value}分`,
      承認状態: '未承認',
      作成日時: new Date(),
      更新日時: new Date(),
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, formData); // 作業記録テーブル
    if (saved) {
      showSuccess(isTemp ? '一時保存しました' : '工数記録を登録しました');
      if (!isTemp) {
        setTimeout(() => {
          window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
        }, 1500);
      }
    }
  }

  // イベントリスナー設定
  loadWorkItems();

  container.querySelector('#work-details').addEventListener('input', updateCharCount);
  container.querySelector('#start-time').addEventListener('change', calculateHours);
  container.querySelector('#end-time').addEventListener('change', calculateHours);
  container.querySelector('#break-time').addEventListener('input', calculateHours);

  container.querySelector('#btn-add-break').addEventListener('click', addBreakRecord);
  container.querySelector('#btn-temp-save').addEventListener('click', () => saveRecord(true));
  container.querySelector('#btn-save').addEventListener('click', () => {
    if (confirm('工数記録を確定しますか？')) {
      saveRecord(false);
    }
  });
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  updateCharCount();
  calculateHours();
}
